export default {
	currentOperator() {
		const email = (appsmith.user?.email || "").trim().toLowerCase();
		const name = (appsmith.user?.name || "").trim();
		if (email) return email;
		if (name) return name;
		return "system";
	},

	sql: {
		str(v) {
		if (v === undefined || v === null || v === "") return "NULL";
		return "'" + String(v).replace(/'/g, "''") + "'";
		},
		num(v) {
		const n = Number(v);
		return Number.isFinite(n) ? String(n) : "NULL";
		},
		arrStr(arr) {
		// Safe Postgres text[] expression for use with = ANY(...)
		if (!arr || arr.length === 0) return "ARRAY[]::text[]";
		const vals = arr.map(x => "'" + String(x).replace(/'/g, "''") + "'");
		return "ARRAY[" + vals.join(", ") + "]::text[]";
		},
		arrBigint(arr) {
		// Safe Postgres bigint[] expression for function args
		if (!arr || arr.length === 0) return "ARRAY[]::bigint[]";
		const vals = arr.map(x => {
			const n = Number(x);
			return Number.isFinite(n) ? String(n) : "NULL";
		}).filter(x => x !== "NULL");
		if (vals.length === 0) return "ARRAY[]::bigint[]";
		return "ARRAY[" + vals.join(", ") + "]::bigint[]";
		},
	},

	sqlNull() {
		return "NULL";
	},

	sqlNumOrNull(v) {
		return this.sql.num(v);
	},

	sqlTimestampOrNull(v) {
		if (v === null || v === undefined || v === "" || v === "NULL") return "NULL";
		return this.sql.str(v);
	},

	selectedLotIds() {
		return this.selectedLotRows()
			.map(r => Number(r.nocopk))
			.filter(Number.isFinite);
	},

	selectedLotIdsSql() {
		return this.selectedLotIds()
			.map(id => Number(id))
			.filter(Number.isFinite)
			.join(",");
	},

	formatSelectedLots() {
		const rows = (tblLots.selectedRows || []);
		if (!rows.length) return "(No lots selected)";
		return rows.map(r => {
		const lotId = r.lot_id ?? r.nocopk;
		const inoc = r.inoculated_at ? moment(r.inoculated_at).format("YYYY-MM-DD") : "";
		const item = r.item_name_mat || "";
		const strain = r.strain_species_strain_mat || "";
		return `${lotId} | inoc:${inoc} | ${item} | ${strain}`.trim();
		}).join("\n");
	},

	lotsTableOriginalRow(row) {
		const id = row?.nocopk;
		return (qLots.data || []).find(r => String(r.nocopk) === String(id)) || row || {};
	},

	locationById(locationId) {
		return (qLocations.data || []).find(l => String(l.nocopk) === String(locationId)) || null;
	},

	locationNameById(locationId) {
		const loc = this.locationById(locationId);
		return String(loc?.name || "").trim();
	},

	lotsTableLocationGroupFromName(name) {
		const lower = String(name || "").trim().toLowerCase();

		if (!lower) return "unknown";

		if (
			lower.includes("consumed") ||
			lower.includes("retired") ||
			lower.includes("compost") ||
			lower.includes("expired") ||
			lower.includes("contaminated") ||
			lower.includes("invalid") ||
			lower.includes("inviable")
		) {
			return "terminal";
		}

		if (lower.includes("freeze dryer") || lower.includes("freeze-dryer")) {
			return "freeze_dryer";
		}

		if (lower.includes("freezer")) {
			return "freezer";
		}

		if (lower.includes("fridge") || lower.includes("refrigerat")) {
			return "fridge";
		}

		if (lower.includes("fruiting")) {
			return "fruiting";
		}

		if (lower.includes("dark room")) {
			return "dark_room";
		}

		if (
			lower.includes("products storage") ||
			lower.includes("product storage") ||
			lower.includes("fulfillment") ||
			lower.includes("shipping") ||
			lower.includes("retail") ||
			lower.includes("market")
		) {
			return "product_storage";
		}

		if (
			lower.includes("new") ||
			lower.includes("receiving") ||
			lower.includes("intake") ||
			lower.includes("staging")
		) {
			return "new_lot";
		}

		if (lower.includes("lab")) {
			return "lab";
		}

		return "other";
	},

	lotsTableLocationEditValidation(row, proposedLocationId) {
		const original = this.lotsTableOriginalRow(row);
		const lotId = original?.nocopk;
		const lotLabel = original?.lot_id || lotId || "Selected lot";
		const status = String(original?.status || "").trim().toLowerCase();

		const fromLocationId = original?.location_id;
		const toLocationId = proposedLocationId ?? row?.location_id;

		const fromName = this.locationNameById(fromLocationId);
		const toName = this.locationNameById(toLocationId);

		const fromGroup = this.lotsTableLocationGroupFromName(fromName);
		const toGroup = this.lotsTableLocationGroupFromName(toName);

		if (!lotId) {
			return {
				ok: false,
				message: "Could not identify the lot being edited."
			};
		}

		if (!toLocationId || !toName) {
			return {
				ok: false,
				message: "Select a valid destination location."
			};
		}

		if (String(fromLocationId) === String(toLocationId)) {
			return {
				ok: true,
				message: ""
			};
		}

		if (
			status.includes("retired") ||
			status.includes("expired") ||
			status.includes("consumed") ||
			status.includes("compost")
		) {
			return {
				ok: false,
				message: `${lotLabel} is terminal/retired and should not be moved from the Lots table.`
			};
		}

		if (toGroup === "terminal") {
			return {
				ok: false,
				message: `${toName} is a terminal location. Use the Retire/Terminal workflow instead.`
			};
		}

		if (fromGroup === "freeze_dryer" || toGroup === "freeze_dryer") {
			return {
				ok: false,
				message: "Freeze Dryer movement should be handled from Products / freeze-dry workflow, not Lots table inline edit."
			};
		}

		if (status === "new" && toGroup !== "new_lot") {
			return {
				ok: false,
				message: "Moving New lots into production or product storage is a workflow action. Use the appropriate process modal instead."
			};
		}

		const sameClassAllowedGroups = [
			"product_storage",
			"fridge",
			"freezer",
			"fruiting",
			"new_lot",
			"lab",
			"dark_room"
		];

		if (
			fromGroup === toGroup &&
			sameClassAllowedGroups.includes(fromGroup)
		) {
			return {
				ok: true,
				message: ""
			};
		}

		if (fromGroup === "dark_room" && ["fridge", "freezer", "fruiting"].includes(toGroup)) {
			return {
				ok: false,
				message: "Moving from Dark Room to Fridge/Freezer/Fruiting is a transition. Use the Transition/Move modal."
			};
		}

		if (toGroup === "product_storage") {
			return {
				ok: false,
				message: "Moving lots into product storage is productizing/package behavior. Use Package Lots."
			};
		}

		return {
			ok: false,
			message: `Inline location edit only supports same-class moves. Use the appropriate workflow to move from ${fromName || "unknown"} to ${toName}.`
		};
	},

	lotsTableLocationOptionsForRow(row) {
		const original = this.lotsTableOriginalRow(row);

		return (qLocations.data || [])
			.filter(loc => {
				if (!loc?.nocopk || !loc?.name) return false;
				if (loc.active === false) return false;

				return this.lotsTableLocationEditValidation(original, loc.nocopk).ok;
			})
			.map(loc => ({
				label: loc.name,
				value: loc.nocopk
			}));
	},

	canSaveLotsTableLocationEdit(row) {
		const original = this.lotsTableOriginalRow(row);
		const newLocationId = row?.location_id;

		if (!original?.nocopk) return false;
		if (!newLocationId) return false;

		if (String(original.location_id) === String(newLocationId)) {
			return false;
		}

		return this.lotsTableLocationEditValidation(row, newLocationId).ok;
	},

	async onLotsTableLocationChanged(row) {
		const validation = this.lotsTableLocationEditValidation(row, row?.location_id);

		if (!validation.ok) {
			showAlert(validation.message, "warning");
			return false;
		}

		return true;
	},

	async saveLotsTableLocationEdit(row) {
		const original = this.lotsTableOriginalRow(row);
		const edited = {
			...original,
			...(row || {})
		};

		const newLocationId = edited?.location_id;
		const validation = this.lotsTableLocationEditValidation(edited, newLocationId);

		if (!validation.ok) {
			showAlert(validation.message, "warning");
			return null;
		}

		await storeValue("lots_table_move_lot_id", original.nocopk);
		await storeValue("lots_table_move_location_id", newLocationId);

		try {
			const res = await qLotsTableMoveLocation.run();
			const movedCount = res?.[0]?.moved_count ?? 0;

			showAlert(`Moved ${movedCount} lot(s).`, "success");

			await qLots.run();
			return res;
		} catch (e) {
			showAlert(e?.message || String(e), "error");
			await storeValue("lots_error", e?.message || String(e));
			return null;
		}
	},

	retireReason() {
		// CheckboxGroup1.selectedValues is usually an array
		const vals = [ radioReason.selectedOptionValue ]; 
		if (!vals.length) return "Retired";
		// prefer Contaminated over Compost over Expired if multiple
		const order = ["Contaminated", "Compost", "Expired"];
		for (const v of order) if (vals.includes(v)) return v;
		return vals[0];
	},

	lotTypeCategories() {
		const t = inpLotType.selectedOptionValue || "All";
		switch (t) {
		case "Grain": return ["grain"];
		case "Substrate": return ["substrate", "casing", "cordyceps_substrate"];
		case "Liquid Culture": return ["lc_flask", "lc_syringe"];
		case "Fruiting Block": return ["fruiting_block", "all_in_one_bag"];
		case "Freeze Dried Mushrooms": return ["freezedriedmushrooms"];
		case "Tray": return ["freezer_tray", "fresh_tray", "empty_tray"];
		case "Agar": return ["agar_flask", "plate"];
		case "Untracked": return ["untracked_source"];
				case "Inoculable": return ["grain", "plate", "lc_flask", "cordyceps_substrate", "all_in_one_bag"];
				case "All":
				default: return [];				
		}
	},

	statusSet() {
		const s = inpLotStatus.selectedOptionValue || "All";
		switch (s) {
		case "New": return ["Planned", "Sterilized", "Pasteurized", "Sealed"];
		case "Colonizing": return ["Inoculated", "Spawned", "Colonizing"];
		case "Colonized/Fridge": return ["FullyColonized", "Fridge", "ColdShock"];
		case "Fruiting": return ["Fruiting"];
		case "Frozen": return ["Frozen"];
		case "Retired": return ["Consumed", "Retired", "Compost", "Composted", "Expired"];
		case "All Active":
			return ["Planned","Sterilized","Pasteurized","Sealed","Inoculated","Spawned","Colonizing","FullyColonized","Fridge","ColdShock","Fruiting","Frozen"];
		case "All":
		default: return [];
		}
	},

	processTypeSet() {
		const out = [];
		if (chkSterilized.isChecked) out.push("sterilize","sterilized");
		if (chkPasteurized.isChecked) out.push("pasteurize","pasteurized");
		return out;
	},

	regulatedMode() {
		const r = chkRegulated.isChecked;
		const u = chkUnRegulated.isChecked;
		if ((r && u) || (!r && !u)) return "all";
		if (r) return "regulated";
		return "unregulated";
	},

	async refresh() {
		txtErrLots.setText("");
			txtShakeContent.setText("");
			inpShakeNotes.setValue("");		
			txtRetireContent.setText("");
			inpRetireNotes.setValue("");
			txtMoveContent.setText("");
			inpMoveNotes.setValue("");
			txtModifyContent.setText("");
			inpModifyNotes.setValue("");
			txtPackageContent.setText("");
			inpPackageNotes.setValue("");
		try {
			await qLots.run();
		} catch (e) {
			txtErrLots.setText(e?.message || String(e));
		}
	},

	async showinoculable() {
		inpLotType.setSelectedOption("Inoculable");
		inpStrains.setSelectedOption("All");
		inpLotStatus.setSelectedOption("New");
		chkSterilized.setValue(true);
		chkPasteurized.setValue(false);
		chkRegulated.setValue(false);
		chkUnRegulated.setValue(false);

		await LotsPage.refresh();
	},

	async showfruiting() {
		inpLotType.setSelectedOption("All");
		inpStrains.setSelectedOption("All");
		inpLotStatus.setSelectedOption("Fruiting");
		chkSterilized.setValue(false);
		chkPasteurized.setValue(false);
		chkRegulated.setValue(false);
		chkUnRegulated.setValue(false);

		await LotsPage.refresh();
	},

	async showrefrigerated() {
		inpLotType.setSelectedOption("All");
		inpStrains.setSelectedOption("All");
		inpLotStatus.setSelectedOption("Colonized/Fridge");
		chkSterilized.setValue(false);
		chkPasteurized.setValue(false);
		chkRegulated.setValue(false);
		chkUnRegulated.setValue(false);

		await LotsPage.refresh();
	},

	async showretired() {
		inpLotType.setSelectedOption("All");
		inpStrains.setSelectedOption("All");
		inpLotStatus.setSelectedOption("Retired");
		chkSterilized.setValue(false);
		chkPasteurized.setValue(false);
		chkRegulated.setValue(false);
		chkUnRegulated.setValue(false);

		await LotsPage.refresh();
	},	

	async showcolonizing() {
		inpLotType.setSelectedOption("All");
		inpStrains.setSelectedOption("All");
		inpLotStatus.setSelectedOption("Colonizing");
		chkSterilized.setValue(false);
		chkPasteurized.setValue(false);
		chkRegulated.setValue(false);
		chkUnRegulated.setValue(false);

		await LotsPage.refresh();
	},	

	async init() {
    txtErrLots.setText("");

    try {
      const requestedLot = String(
        appsmith.URL?.queryParams?.lot || ""
      ).trim();
      const validRequestedLot = !requestedLot || /^(LOT)-[A-Za-z0-9-]+$/i.test(requestedLot);

      const previousSelection = String(
        inpStrains.selectedOptionValue || "All"
      );
      const speciesRows = await qSpecies.run();
      const validSelections = new Set([
        "All",
        ...(speciesRows || [])
          .map(row => String(row?.species_strain || "").trim())
          .filter(Boolean)
      ]);

      if (!validSelections.has(previousSelection)) {
        await inpStrains.setSelectedOption("All");
      }

      await LotsPage.refresh();

      if (requestedLot) {
        if (!validRequestedLot) {
          txtErrLots.setText(`Invalid Lot deep link: ${requestedLot}`);
          return;
        }

        const rows = qLots.data || [];
        const requestedIndex = rows.findIndex(row =>
          String(row?.lot_id || "").trim().toLowerCase() === requestedLot.toLowerCase()
        );

        if (requestedIndex < 0) {
          txtErrLots.setText(`Lot not found on Lots page: ${requestedLot}`);
          return;
        }

        // qLots places a deep-linked Lot first even when the current filters
        // would normally hide it. Reset the table, then explicitly replace
        // its multi-row selection with only the deep-linked Lot.
        await resetWidget("tblLots", true);
        await tblLots.setSelectedRowIndices([requestedIndex]);

        if (String(appsmith.URL?.queryParams?.source || "").toLowerCase() === "qr") {
          showAlert(`Loaded ${rows[requestedIndex].lot_id} from QR scan.`, "success");
        }
      }
    } catch (e) {
      txtErrLots.setText(e?.message || String(e));
    }
  },

	selectedLotRows() {
		return (tblLots.selectedRows || []).filter(r => r && r.nocopk != null);
	},

	lotIsRetired(row) {
		const status = String(row?.status || "").toLowerCase();
		return ["consumed", "expired", "retired", "compost", "composted", "compose"].some(s => status.includes(s));
	},

	lotLocationName(row) {
		const id = row?.location_id;
		const loc = (qLocations.data || []).find(l => String(l.nocopk) === String(id));
		return String(loc?.name || row?.location_name || row?.location || "");
	},

	lotModalValidation(actionOrOptions = {}) {
		const rows = this.selectedLotRows();
		const action = typeof actionOrOptions === "string" ? actionOrOptions : null;
		const options = typeof actionOrOptions === "object" && actionOrOptions !== null ? actionOrOptions : {};

		const rulesByAction = {
			shake: {
				requireAny: true,
				allowedCategories: ["grain"],
				requireInoculated: true,
				message: "Select one or more active inoculated grain lots to shake."
			},
			retire: {
				requireAny: true,
				message: "Select one or more active lots to retire."
			},
			modify: {
				requireAny: true,
				allowedCategories: ["fruiting_block", "all_in_one_bag"],
				message: "Select one or more active fruiting block or all-in-one bag lots to modify."
			},
			move: {
				requireAny: true,
				requireInoculatedOrSpawned: true,
				disallowFruitingLocation: true,
				message: "Select one or more active inoculated or spawned lots that are not already in Fruiting."
			},
			package: {
				requireAny: true,
				allowedCategories: ["grain", "substrate", "casing", "fruiting_block", "all_in_one_bag"],
				message: "Select one or more active grain, substrate, casing, fruiting block, or all-in-one bag lots to package independently."
			},
			inoculate: {
				requireAny: true,
				allowedCategories: ["grain", "lc_flask", "plate", "cordyceps_substrate", "all_in_one_bag"],
				requireNoStrain: true,
				requireNotInoculated: true,
				message: "Select one or more active grain, LC flask, plate, cordyceps substrate, or all-in-one bag lots that have not already been inoculated or assigned a strain."
			},
			draw_syringes: {
				requireSingle: true,
				allowedCategories: ["lc_flask"],
				message: "Select exactly one active LC flask lot to draw syringes."
			},
			harvest: {
				requireSingle: true,
				allowedCategories: ["fruiting_block", "cordyceps_substrate", "all_in_one_bag"],
				message: "Select exactly one active fruiting block, cordyceps substrate, or all-in-one bag lot to harvest."
			}
		};

		const rules = {
			...(action ? (rulesByAction[action] || {}) : {}),
			...options
		};

		if (rules.requireSingle && rows.length !== 1) {
			return { ok: false, message: rules.message || "Select exactly one valid lot." };
		}

		if ((rules.requireAny || !rules.requireSingle) && rows.length === 0) {
			return { ok: false, message: rules.message || "Select one or more valid lots." };
		}

		for (const row of rows) {
			const label = row.lot_id || row.nocopk || "Selected lot";
			const category = String(row.item_category_mat || "");

			if (rules.allowedCategories && !rules.allowedCategories.includes(category)) {
				return { ok: false, message: `${label} has category ${category || "(blank)"}; expected ${rules.allowedCategories.join(", ")}.` };
			}

			if (!rules.allowRetired && this.lotIsRetired(row)) {
				return { ok: false, message: `${label} is retired or unavailable (${row.status || "unknown status"}).` };
			}

			if (rules.requireInoculated && !row.inoculated_at) {
				return { ok: false, message: `${label} must be inoculated.` };
			}

			if (rules.requireInoculatedOrSpawned && !(row.inoculated_at || row.spawned_at)) {
				return { ok: false, message: `${label} must be inoculated or spawned.` };
			}

			if (rules.requireNoStrain && row.strain_species_strain_mat) {
				return { ok: false, message: `${label} already has a strain (${row.strain_species_strain_mat}).` };
			}

			if (rules.requireNotInoculated && row.inoculated_at) {
				return { ok: false, message: `${label} was already inoculated (${row.inoculated_at}).` };
			}

			if (rules.disallowFruitingLocation && this.lotLocationName(row).toLowerCase().includes("fruiting")) {
				return { ok: false, message: `${label} is already located in Fruiting.` };
			}
		}

		return { ok: true, message: "" };
	},

	canOpenLotModal(actionOrOptions = {}) {
		if (actionOrOptions === "package") {
			return this.packageSelectionValidation().ok;
		}
		return this.lotModalValidation(actionOrOptions).ok;
	},

	validateAndWarnLotModal(actionOrOptions = {}, fallbackMessage = "Invalid lot selection for this action.") {
		const result = actionOrOptions === "package"
			? this.packageSelectionValidation()
			: this.lotModalValidation(actionOrOptions);
		if (!result.ok) {
			showAlert(result.message || fallbackMessage, "warning");
			return false;
		}
		return true;
	},

	isPackageSubmitting() {
		return appsmith.store.lots_package_submitting === true;
	},

	canSubmitShake() {
		return this.canOpenLotModal("shake");
	},

	canSubmitRetire() {
		return (
			this.canOpenLotModal("retire") &&
			!!radioReason.selectedOptionValue
		);
	},

	moveLocationOptions() {
		return qFridgeFruitingLocations.data || [];
	},

	defaultMoveLocationId(mode = radioMoveTransitionMode.selectedOptionValue || "FullyColonized") {
		const opts = LotsPage.moveLocationOptions();
		const lowerMode = String(mode || "").toLowerCase();

		const findByName = (...parts) => opts.find(loc => {
			const name = String(loc.name || "").trim().toLowerCase();
			return parts.some(part => name.includes(part));
		});

		if (lowerMode === "fullycolonized") {
			const exactDarkRoom = opts.find(loc => String(loc.name || "").trim().toLowerCase() === "dark room");
			return (exactDarkRoom || findByName("dark room"))?.nocopk || "";
		}

		if (["fridge", "coldshock"].includes(lowerMode)) {
			return findByName("fridge", "refrigerator")?.nocopk || "";
		}

		if (["fruiting", "startfruiting"].includes(lowerMode)) {
			return findByName("fruiting")?.nocopk || "";
		}

		return "";
	},

	async onMoveTransitionModeChanged() {
		const defaultLocationId = LotsPage.defaultMoveLocationId();
		await inpMoveLocation.setSelectedOption(defaultLocationId || "");
	},

	canSubmitMove() {
		const mode = radioMoveTransitionMode.selectedOptionValue || "";

		return (
			this.canOpenLotModal("move") &&
			!!mode &&
			!!inpMoveLocation.selectedOptionValue
		);
	},

	canSubmitModify() {
		return (
			this.canOpenLotModal("modify") &&
			(chkbxgrpModifyAction.selectedValues || []).length > 0
		);
	},

	packageLotWeightG(row) {
		const value = Number(row?.packageable_weight_g);
		return Number.isFinite(value) && value > 0 ? +value.toFixed(2) : NaN;
	},

	selectedPackageRows() {
		return LotsPage.selectedLotRows().map(row => ({
			row,
			weightG: LotsPage.packageLotWeightG(row)
		}));
	},

	selectedPackageWeightG() {
		const rows = LotsPage.selectedPackageRows();
		return rows.length === 1 && Number.isFinite(rows[0].weightG)
			? rows[0].weightG
			: "";
	},

	packageSelectionValidation() {
		const base = LotsPage.lotModalValidation("package");
		if (!base.ok) return { ...base, rows: [] };

		const rows = LotsPage.selectedPackageRows();
		const invalid = rows.find(entry => !Number.isFinite(entry.weightG) || entry.weightG <= 0);
		if (invalid) {
			const lot = invalid.row?.lot_id || invalid.row?.nocopk || "Selected lot";
			return {
				ok: false,
				rows,
				message: `${lot} does not have a packageable weight. Set lot unit_size or an item default unit size.`
			};
		}

		return { ok: true, message: "", rows };
	},

	packageSelectedLotsSummary() {
		const validation = LotsPage.packageSelectionValidation();
		if (!validation.rows?.length) return "No lots selected.";

		return validation.rows.map((entry, index) => {
			const row = entry.row || {};
			const lot = row.lot_id || row.nocopk || `Lot ${index + 1}`;
			const item = row.item_name_mat || row.item_name || row.item_category_mat || "Unknown item";
			const strain = row.strain_species_strain_mat || "";
			const category = String(row.item_category_mat || "").toLowerCase();
			const unitSize = Number(row.unit_size);
			const poundBased = ["grain", "substrate", "casing", "fruiting_block", "all_in_one_bag"].includes(category);
			const poundText = poundBased && Number.isFinite(unitSize) && unitSize > 0
				? `${unitSize.toFixed(2).replace(/\.?0+$/, "")} lb / `
				: "";
			const strainText = strain ? ` — ${strain}` : "";
			return `${index + 1}. ${lot} — ${item} — ${poundText}${entry.weightG.toFixed(2)} g${strainText}`;
		}).join("\n");
	},

	defaultPackageCount() {
		return "1";
	},

	defaultPackageSizeG() {
		const weight = LotsPage.selectedPackageWeightG();
		return weight ? String(weight) : "";
	},

	requestedPackageWeightG() {
		const count = Number(inpPackageCount.text);
		const sizeG = Number(inpPackageSizeG.text);

		if (!Number.isFinite(count) || !Number.isFinite(sizeG)) {
			return NaN;
		}

		return count * sizeG;
	},

	hasEnoughPackageWeight() {
		const requested = LotsPage.requestedPackageWeightG();
		const available = LotsPage.selectedPackageWeightG();

		return Number.isFinite(requested)
			&& requested > 0
			&& available > 0
			&& requested <= available;
	},

	packageStorageLocationOptions() {
		const invalidNameParts = [
			"dark room",
			"fruiting",
			"freeze",
			"freezer",
			"fridge",
			"refrigerat",
			"cold shock",
			"lab",
			"shipped",
			"consumed",
			"compost",
			"expired"
		];

		const preferredNameParts = [
			"products storage",
			"product storage",
			"finished",
			"retail",
			"customer",
			"market"
		];

		return (qProductLocations.data || [])
			.filter(l => {
				const name = String(l.name || "").trim();
				const lower = name.toLowerCase();

				if (!name) return false;
				if (l.active === false) return false;

				if (invalidNameParts.some(part => lower.includes(part))) {
					return false;
				}

				return preferredNameParts.some(part => lower.includes(part));
			})
			.map(l => ({
				label: l.name,
				value: l.nocopk
			}));
	},

	defaultPackageStorageLocationId() {
		const opts = this.packageStorageLocationOptions();

		const productsStorage = opts.find(o =>
			String(o.label || "").trim().toLowerCase() === "products storage"
		);

		return (productsStorage || opts[0])?.value || "";
	},

	canSubmitPackage() {
		if (LotsPage.isPackageSubmitting()) return false;

		const validation = LotsPage.packageSelectionValidation();
		const count = Number(inpPackageCount.text);
		const selectedLocationId = inpPackageStorageLocation.selectedOptionValue;
		const validLocationIds = LotsPage.packageStorageLocationOptions().map(o => String(o.value));

		return validation.ok
			&& validation.rows.length > 0
			&& Number.isFinite(count)
			&& count === 1
			&& !!selectedLocationId
			&& validLocationIds.includes(String(selectedLocationId));
	},

	async verifyShakeableLots() {
		return this.validateAndWarnLotModal("shake", "Select shakeable lots to shake.");
	},
	async verifyModifiableLots() {
		return this.validateAndWarnLotModal("modify", "Select only active fruiting blocks to modify.");
	},
	async verifyMoveableLots() {
		return this.validateAndWarnLotModal("move", "Select moveable lots to transition.");
	},
	async verifyRetireableLots() {
		return this.validateAndWarnLotModal("retire", "Select active lots to retire.");
	},
	async verifyPackageableLots() {
		return this.validateAndWarnLotModal("package", "Select valid lots to package.");
	},

	async openShakeModal() {
		if (!this.validateAndWarnLotModal("shake", "Select shakeable lots to shake.")) return;
		txtShakeContent.setText(this.formatSelectedLots());
		await showModal(modalShakeLots.name);
	},

	async openRetireModal() {
		if (!this.validateAndWarnLotModal("retire", "Select retireable lots to retire.")) return;

		txtRetireContent.setText(this.formatSelectedLots());

		const today = moment().startOf("day");
		const rows = this.selectedLotRows();
		const expiredRows = rows.filter(row => {
			if (!row.use_by) return false;
			const useBy = moment(row.use_by).startOf("day");
			return useBy.isValid() && useBy.isBefore(today);
		});

		if (expiredRows.length > 0) {
			radioReason.setValue("Expired");
			showAlert(
				`${expiredRows.length} selected lot(s) are past use_by. Expired is recommended as the terminal reason.`,
				"warning"
			);
		}

		await showModal(modalRetireLots.name);
	},

	async openModifyModal() {
		if (!this.validateAndWarnLotModal("modify", "Select only modifiable fruiting blocks.")) return;
		await resetWidget("chkbxgrpModifyAction", true);
		await inpModifyNotes.setValue("");
		await txtModifyContent.setText(this.formatSelectedLots());
		await showModal(modalModifyLots.name);
	},	

	async openMoveModal() {
		if (!this.validateAndWarnLotModal("move", "Select moveable lots to transition.")) return;
		txtMoveContent.setText(this.formatSelectedLots());
		await qFridgeFruitingLocations.run();
		await radioMoveTransitionMode.setValue("FullyColonized");
		await LotsPage.onMoveTransitionModeChanged();
		await showModal(modalMoveLots.name);
	},	

	async openPackageModal() {
		const validation = LotsPage.packageSelectionValidation();
		if (!validation.ok) {
			showAlert(validation.message || "Select one or more packageable lots.", "warning");
			return;
		}

		await txtPackageContent.setText(LotsPage.packageSelectedLotsSummary());
		await inpPackageCount.setValue("1");
		await inpPackageSizeG.setValue(
			validation.rows.length === 1 ? String(validation.rows[0].weightG) : ""
		);
		await inpPackageNotes.setValue("");

		await qLocations.run();

		const defaultLocationId = LotsPage.defaultPackageStorageLocationId();
		if (defaultLocationId) {
			await inpPackageStorageLocation.setSelectedOption(defaultLocationId);
		} else {
			await inpPackageStorageLocation.setSelectedOption("");
			showAlert("No product-ready storage location was found.", "warning");
		}

		await storeValue("lots_package_submitting", false);
		await showModal(modalPackageLots.name);
	},

	selectedLotsSummary() {
		const rows = (tblLots.selectedRows || []).filter(r => r && r.nocopk != null);
		if (!rows.length) return "No lots selected.";
		return rows.map(r => {
		const lot = r.lot_id || r.lotId || r.lot_id_mat || r.nocopk;
		const inoc = r.inoculated_at || r.inoculatedAt || r.created_at || r.createdAt || "";
		const item = r.item_name_mat || r.item_name || r.itemName || "";
		const strain = r.strain_species_strain_mat || r.strain_species_strain || r.species_strain || "";
		return `${lot} | inoculated: ${inoc || "—"} | ${item} | ${strain}`;
		}).join("\n");
	},

	async shakeSelectedLots() {

			if (!this.selectedLotIds().length) return showAlert("Select one or more lots first.", "warning");

			let lotsshaken;
		try {
		lotsshaken = await qShakeLots.run();
		// refresh downstream view
		} catch (e) {
				showAlert("Error flagging lots as shaken: " + (e && e.message) ? e.message : String(e), 'error');
		await storeValue('lots_error', (e && e.message) ? e.message : String(e));
				return;
		}		

			showAlert("Shook " + lotsshaken[0].shaken_count + " lot(s).", 'success');

			txtShakeContent.setText("");
			inpShakeNotes.setValue("");		
		closeModal(modalShakeLots.name);
		await qLots.run();
	},

	async retireSelectedLots() {

			if (!this.selectedLotIds().length) return showAlert("Select one or more lots first.", "warning");

			let lotsretired;
		try {
		lotsretired = await qRetireLots.run();
		// refresh downstream view
		} catch (e) {
				showAlert("Error retiring lots: " + (e && e.message) ? e.message : String(e), 'error');
		await storeValue('lots_error', (e && e.message) ? e.message : String(e));
				return;
		}	

			showAlert("Retired " + lotsretired[0].retired_count + " lot(s).", 'success');

			txtRetireContent.setText("");
			inpRetireNotes.setValue("");		
		closeModal(modalRetireLots.name);
		await qLots.run();
	},

	async moveSelectedLots() {
		if (!this.selectedLotIds().length) {
			return showAlert("Select one or more lots first.", "warning");
		}

		if (!this.canSubmitMove()) {
			showAlert("Select a transition mode and, when required, a destination location.", "warning");
			return;
		}

		let lotsmoved;
		try {
			lotsmoved = await qMoveLots.run();
		} catch (e) {
			showAlert("Error moving lots: " + ((e && e.message) ? e.message : String(e)), "error");
			await storeValue("lots_error", (e && e.message) ? e.message : String(e));
			return;
		}

		showAlert("Transitioned " + lotsmoved[0].moved_count + " lot(s).", "success");

		txtMoveContent.setText("");
		inpMoveNotes.setValue("");
		closeModal(modalMoveLots.name);
		await qLots.run();
	},	

	async modifySelectedLots() {

			if (!this.selectedLotIds().length) return showAlert("Select one or more lots first.", "warning");

			let lotsmodified;
		try {
		lotsmodified = await qModifyLots.run();
		// refresh downstream view
		} catch (e) {
				showAlert("Error modifying lots: " + (e && e.message) ? e.message : String(e), 'error');
		await storeValue('lots_error', (e && e.message) ? e.message : String(e));
				return;
		}		

			showAlert("Modified " + lotsmodified[0].modified_count + " lot(s).", 'success');

			txtModifyContent.setText("");
			inpModifyNotes.setValue("");		
		closeModal(modalModifyLots.name);
		await qLots.run();
	},	

	async packageSelectedLots() {
		if (LotsPage.isPackageSubmitting()) return;

		const validation = LotsPage.packageSelectionValidation();
		if (!validation.ok) {
			showAlert(validation.message || "Select one or more packageable lots.", "warning");
			return;
		}

		if (!LotsPage.canSubmitPackage()) {
			showAlert("Select a product-ready storage location before packaging.", "warning");
			return;
		}

		await storeValue("lots_package_submitting", true);

		try {
			const response = await qPackageLots.run();
			const data = (qPackageLots.data && qPackageLots.data.length) ? qPackageLots.data : response;
			const returnedCount = Number(data?.[0]?.packaged_count);
			const packagedCount = Number.isFinite(returnedCount) ? returnedCount : validation.rows.length;

			showAlert(`Packaged ${packagedCount} lot(s) as ${packagedCount} independent product(s).`, "success");

			await txtPackageContent.setText("");
			await inpPackageNotes.setValue("");
			closeModal(modalPackageLots.name);

			await qLots.run();
			await resetWidget("tblLots", true);
			return data;
		} catch (e) {
			const message = e && e.message ? e.message : String(e);
			showAlert("Error packaging lots: " + message, "error");
			await storeValue("lots_error", message);
			return null;
		} finally {
			await storeValue("lots_package_submitting", false);
		}
	},


};

