publishedCollection.body:
export default {
	sql: {
		str(v) {
			if (v === undefined || v === null || v === "") return "NULL";
			return "'" + String(v).replace(/'/g, "''") + "'";
		},
		num(v) {
			const n = Number(v);
			return Number.isFinite(n) ? String(n) : "NULL";
		},
		arrBigint(arr) {
			if (!arr || arr.length === 0) return "ARRAY[]::bigint[]";
			const vals = arr.map(x => {
				const n = Number(x);
				return Number.isFinite(n) ? String(n) : "NULL";
			}).filter(x => x !== "NULL");
			if (vals.length === 0) return "ARRAY[]::bigint[]";
			return "ARRAY[" + vals.join(", ") + "]::bigint[]";
		}
	},

	currentOperator() {
		const email = (appsmith.user?.email || "").trim().toLowerCase();
		const name = (appsmith.user?.name || "").trim();
		if (email) return email;
		if (name) return name;
		return "system";
	},

	syringeItemOptions() {
		return (qSyringeItems.data || [])
			.filter(i => i && i.nocopk)
			.map(i => ({
				label: i.label || `${i.name || i.item_id || i.nocopk}`,
				value: i.nocopk,
				default_unit_size_ml: i.default_unit_size_ml
			}));
	},

	defaultSyringeItemId() {
		const opts = this.syringeItemOptions();
		return opts[0]?.value || "";
	},

	selectedSyringeItem() {
		const selected = selSyringeItem.selectedOptionValue;
		return (qSyringeItems.data || [])
			.find(i => String(i.nocopk) === String(selected)) || null;
	},

	selectedFlaskLot() {
		return LotsPage.selectedLotRows()[0] || null;
	},

	selectedFlaskRemainingMl() {
		const row = LotsDrawSyringes.selectedFlaskLot();
		const remaining = Number(row?.remaining_volume_ml);
		return Number.isFinite(remaining) ? remaining : 0;
	},

	requestedSyringeVolumeMl() {
		const count = Number(inpSyringeCount.text);
		const mlEach = Number(inpSyringeMlEach.text);

		if (!Number.isFinite(count) || !Number.isFinite(mlEach)) {
			return NaN;
		}

		return count * mlEach;
	},

	hasEnoughSelectedFlaskVolume() {
		const requested = LotsDrawSyringes.requestedSyringeVolumeMl();
		const remaining = LotsDrawSyringes.selectedFlaskRemainingMl();

		return Number.isFinite(requested)
			&& requested > 0
			&& remaining > 0
			&& requested <= remaining;
	},	

	canSubmitDrawSyringes() {
		const count = Number(inpSyringeCount.text);
		const mlEach = Number(inpSyringeMlEach.text);
		const selectedLocationId = selDrawSyringeLocation.selectedOptionValue;
		const validLocationIds = LotsDrawSyringes.drawSyringeLocationOptions()
			.map(o => String(o.value));

		const selectedSyringeItemId = selSyringeItem.selectedOptionValue;
		const validSyringeItemIds = LotsDrawSyringes.syringeItemOptions()
			.map(o => String(o.value));

		return LotsPage.canOpenLotModal("draw_syringes")
			&& Number.isFinite(count)
			&& count > 0
			&& Number.isFinite(mlEach)
			&& mlEach > 0
			&& LotsDrawSyringes.hasEnoughSelectedFlaskVolume()
			&& !!selectedLocationId
			&& validLocationIds.includes(String(selectedLocationId))
			&& !!selectedSyringeItemId
			&& validSyringeItemIds.includes(String(selectedSyringeItemId));
	},

	drawSyringeLocationOptions() {
		const invalidNameParts = [
			"dark room",
			"fruiting",
			"shipping",
			"fulfillment",
			"products storage",
			"product storage",
			"lab",
			"shipped",
			"consumed",
			"compost",
			"expired"
		];

		return (qProductLocations.data || [])
			.filter(l => {
				const name = String(l.name || "").trim();
				const lower = name.toLowerCase();

				if (!name) return false;
				if (l.active === false) return false;

				const isRefrigerated =
					lower.includes("fridge") ||
					lower.includes("refrigerat");

				if (!isRefrigerated) return false;

				return !invalidNameParts.some(part => lower.includes(part));
			})
			.map(l => ({
				label: l.name,
				value: l.nocopk
			}));
	},

	defaultDrawSyringeLocationId() {
		const opts = LotsDrawSyringes.drawSyringeLocationOptions();

		const fridge = opts.find(o =>
			String(o.label || "").trim().toLowerCase() === "fridge"
		);

		return (fridge || opts[0])?.value || "";
	},

	async openDrawSyringesModal() {
		if (!LotsPage.validateAndWarnLotModal("draw_syringes", "Select exactly one active LC flask lot first.")) return;

		inpSyringeCount.setValue("1");
		inpSyringeMlEach.setValue("10");
		inpDrawSyringesNotes.setValue("");

		Promise.allSettled([
  		qProductLocations.run(),
  		qSyringeItems.run()
		]).finally(async () => {
			const defaultSyringeItemId = LotsDrawSyringes.defaultSyringeItemId();
			if (defaultSyringeItemId) {
				await selSyringeItem.setSelectedOption(defaultSyringeItemId);
			} else {
				await selSyringeItem.setSelectedOption("");
				showAlert("No active LC syringe item was found.", "warning");
			}

			const defaultLocationId = LotsDrawSyringes.defaultDrawSyringeLocationId();
			if (defaultLocationId) {
				await selDrawSyringeLocation.setSelectedOption(defaultLocationId);
			} else {
				await selDrawSyringeLocation.setSelectedOption("");
				showAlert(
					"No refrigerated syringe storage location was found. Add or activate a Fridge/Refrigerated location before drawing syringes.",
					"warning"
				);
			}

			await showModal(modalDrawSyringes.name);
		});
	},

	async drawSyringesFromSelectedFlask() {
		if (!LotsPage.canOpenLotModal("draw_syringes")) {
			showAlert("Select exactly one active LC flask lot first.", "warning");
			return;
		}

		const count = Number(inpSyringeCount.text);
		const mlEach = Number(inpSyringeMlEach.text);
		const mode = selDrawSyringeOutputType.selectedOptionValue || "product";
		const location = selDrawSyringeLocation.selectedOptionValue;
		const validLocationIds = LotsDrawSyringes.drawSyringeLocationOptions()
			.map(o => String(o.value));

		if (!Number.isFinite(count) || count <= 0) {
			showAlert("Enter a syringe count greater than 0.", "warning");
			return;
		}

		if (!Number.isFinite(mlEach) || mlEach <= 0) {
			showAlert("Enter mL per syringe greater than 0.", "warning");
			return;
		}

		if (!location || !validLocationIds.includes(String(location))) {
			showAlert("Select a refrigerated Storage Location for drawn syringes.", "warning");
			return;
		}

		const requestedMl = count * mlEach;
		const remainingMl = LotsDrawSyringes.selectedFlaskRemainingMl();

		if (!Number.isFinite(remainingMl) || remainingMl <= 0) {
			showAlert("Selected LC flask has no remaining volume.", "warning");
			return;
		}

		if (requestedMl > remainingMl) {
			showAlert(`Not enough LC volume. Need ${requestedMl} ml, have ${remainingMl} ml.`, "warning");
			return;
		}

		try {
			const res = mode === "product"
				? await qDrawSyringeProducts.run()
				: await qDrawSyringes.run();

			showAlert(
				mode === "product" ? "Syringe products created." : "Syringe lots created.",
				"success"
			);

			closeModal(modalDrawSyringes.name);
			await LotsPage.refresh();
			return res;
		} catch (e) {
			showAlert(e?.message || String(e), "error");
			return null;
		}
	},
};

