export default {
  safeParse(s) {
    try {
      if (!s) return {};
      if (typeof s === "object") return s;
      return JSON.parse(s);
    } catch (e) {
      return {
        _raw: s,
        _error: String(e)
      };
    }
  },

  durationDays(interval) {
    if (!interval) return "";
    const s = String(interval);
    const m = s.match(/(-?\d+)\s+days?/i);
    if (m) return m[1];
    return s;
  },

  monthlyYieldChartData(rows) {
    const data = (rows || []).map(r => ({
      x: r.month,
      y: Number(r.total_harvest_g || 0)
    }));

    return {
      series: [{
        seriesName: "Total harvest (g)",
        data
      }]
    };
  },

  contamMonthlyChartData(rows) {
    const data = (rows || []).map(r => ({
      x: r.month,
      y: Number(r.contamination_rate || 0)
    }));

    return {
      series: [{
        seriesName: "Contamination rate",
        data
      }]
    };
  },

  async init() {
