export default {
  sql: {
    str(v) {
      if (v === undefined || v === null || v === "") return "NULL";
      return "'" + String(v).replace(/'/g, "''") + "'";
    },

    num(v) {
      const n = Number(v);
      return Number.isFinite(n) ? String(n) : "NULL";
    },

    arrBigint(arr) {
      if (!arr || arr.length === 0) return "ARRAY[]::bigint[]";

      const vals = arr
        .map(x => Number(x))
        .filter(Number.isFinite)
        .map(String);

      if (vals.length === 0) return "ARRAY[]::bigint[]";

      return "ARRAY[" + vals.join(", ") + "]::bigint[]";
    }
  },

  currentOperator() {
    const email = (appsmith.user?.email || "").trim().toLowerCase();
    const name = (appsmith.user?.name || "").trim();

    if (email) return email;
    if (name) return name;

    return "system";
  },

  normalizeToken(value) {
    return String(value || "")
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9]/g, "");
  },

  normalizeCategory(value) {
    return LotsInoculate.normalizeToken(value);
  },

  normalizeStatus(value) {
    return LotsInoculate.normalizeToken(value);
  },

  selectedLotRows() {
    const visibleIds = new Set(
      (qLots.data || [])
        .map(r => Number(r.nocopk))
        .filter(Number.isFinite)
    );

    return (tblLots.selectedRows || [])
      .filter(r => r && r.nocopk != null)
      .filter(r => {
        const id = Number(r.nocopk);
        return Number.isFinite(id) && visibleIds.has(id);
      });
  },

  selectedLotIds() {
    return LotsInoculate.selectedLotRows()
      .map(r => Number(r.nocopk))
      .filter(Number.isFinite);
  },

  selectedInocSourceLot() {
    const selected = tblInocSourceLots.selectedRow;

    if (!selected || selected.nocopk == null) return null;

    const selectedId = Number(selected.nocopk);

    if (!Number.isFinite(selectedId)) return null;

    const visibleIds = new Set(
      (qSourceLotsSearch.data || [])
        .map(r => Number(r.nocopk))
        .filter(Number.isFinite)
    );

    if (!visibleIds.has(selectedId)) return null;

    return selected;
  },

  formatSelectedLots() {
    const rows = LotsInoculate.selectedLotRows();

    if (!rows.length) return "(No lots selected)";

    return rows.map(r => {
      const lotId = r.lot_id ?? r.nocopk;
      const inoc = r.inoculated_at
        ? moment(r.inoculated_at).format("YYYY-MM-DD")
        : "";
      const item = r.item_name_mat || "";
      const strain = r.strain_species_strain_mat || "";

      return `${lotId} | inoc:${inoc} | ${item} | ${strain}`.trim();
    }).join("\n");
  },

  lotIsRetired(row) {
    const status = LotsInoculate.normalizeStatus(row?.status);

    return [
      "consumed",
      "expired",
      "retired",
      "compost",
      "composted",
      "compose",
      "deleted"
    ].includes(status);
  },

  lotModalValidation(actionOrOptions = {}) {
    const rows = LotsInoculate.selectedLotRows();
    const action =
      typeof actionOrOptions === "string"
        ? actionOrOptions
        : null;

    const options =
      typeof actionOrOptions === "object" && actionOrOptions !== null
        ? actionOrOptions
        : {};

    const rulesByAction = {
      inoculate: {
        requireAny: true,
        allowedCategories: [
          "grain",
          "lc_flask",
          "plate",
          "cordyceps_substrate",
          "all_in_one_bag"
        ],
        requireNoStrain: true,
        requireNotInoculated: true,
        message: "Select one or more active grain, LC flask, plate, cordyceps substrate, or all-in-one bag lots that have not already been inoculated or assigned a strain."
      }
    };

    const rules = {
      ...(action ? (rulesByAction[action] || {}) : {}),
      ...options
    };

    if (rules.requireSingle && rows.length !== 1) {
      return {
        ok: false,
        message: rules.message || "Select exactly one valid lot."
      };
    }

    if ((rules.requireAny || !rules.requireSingle) && rows.length === 0) {
      return {
        ok: false,
        message: rules.message || "Select one or more valid lots."
      };
    }

    const allowedCategories = (rules.allowedCategories || [])
      .map(c => LotsInoculate.normalizeCategory(c));

    for (const row of rows) {
      const label = row.lot_id || row.nocopk || "Selected lot";
      const category = LotsInoculate.normalizeCategory(row.item_category_mat);

      if (
        allowedCategories.length > 0 &&
        !allowedCategories.includes(category)
      ) {
        return {
          ok: false,
          message: `${label} has category ${row.item_category_mat || "(blank)"}; expected ${rules.allowedCategories.join(", ")}.`
        };
      }

      if (!rules.allowRetired && LotsInoculate.lotIsRetired(row)) {
        return {
          ok: false,
          message: `${label} is retired or unavailable (${row.status || "unknown status"}).`
        };
      }

      if (rules.requireNoStrain && row.strain_species_strain_mat) {
        return {
          ok: false,
          message: `${label} already has a strain (${row.strain_species_strain_mat}).`
        };
      }

      if (rules.requireNotInoculated && row.inoculated_at) {
        return {
          ok: false,
          message: `${label} was already inoculated (${row.inoculated_at}).`
        };
      }
    }

    return {
      ok: true,
      message: ""
    };
  },

  canOpenLotModal(actionOrOptions = {}) {
    return LotsInoculate.lotModalValidation(actionOrOptions).ok;
  },

  validateAndWarnLotModal(
    actionOrOptions = {},
    fallbackMessage = "Invalid lot selection for this action."
  ) {
    const result = LotsInoculate.lotModalValidation(actionOrOptions);

    if (!result.ok) {
      showAlert(result.message || fallbackMessage, "warning");
      return false;
    }

    return true;
  },

  async refresh() {
    await Promise.allSettled([
      qLots.run(),
      qSourceLotsSearch.run(),
      qInocLocations.run()
    ]);

    resetWidget("tblLots", false);
    await LotsInoculate.resetInoculateFormState();

    const defaultLoc = (qInocLocations.data || []).find(l =>
      String(l.name || "").trim().toLowerCase() === "dark room"
    ) || (qInocLocations.data || [])[0];

    await selInoculateLocation.setSelectedOption(defaultLoc?.nocopk || "");
  },
  sourceLotValidation() {
    const src = LotsInoculate.selectedInocSourceLot();

    if (!src) {
      return {
        ok: false,
        source: null,
        message: "Select a valid SOURCE lot from the current Source Lots table."
      };
    }

    const normalize = LotsInoculate.normalizeCategory || LotsInoculate.normalizeToken;
    const sourceCategory = normalize(src.item_category_mat);
    const sourceStatus = normalize(src.status);

    const allowedSourceCategories = [
      "grain",
      "lcflask",
      "lcsyringe",
      "plate",
      "agarplate",
      "untrackedsource"
    ];

    const allowedSourceStatuses = [
      "inoculated",
      "colonizing",
      "fullycolonized",
      "fridge",
      "coldshock"
    ];

    const terminalStatuses = [
      "consumed",
      "expired",
      "retired",
      "compost",
      "composted",
      "deleted"
    ];

    if (!allowedSourceCategories.includes(sourceCategory)) {
      return {
        ok: false,
        source: src,
        message: `Selected source lot has invalid category: ${src.item_category_mat || "(blank)"}.`
      };
    }

    if (terminalStatuses.includes(sourceStatus)) {
      return {
        ok: false,
        source: src,
        message: `Selected source lot is not available for inoculation. Status: ${src.status || "(blank)"}.`
      };
    }

    if (!allowedSourceStatuses.includes(sourceStatus)) {
      return {
        ok: false,
        source: src,
        message: `Selected source lot is not available for inoculation. Status: ${src.status || "(blank)"}.`
      };
    }

    if (LotsInoculate.sourceNeedsVolume(src)) {
      const availableRaw =
        src.remaining_volume_ml ??
        src.lc_volume_ml ??
        src.total_volume_ml;

      const available = Number(availableRaw);

      if (!Number.isFinite(available) || available <= 0) {
        return {
          ok: false,
          source: src,
          message: "Selected source lot has no remaining source volume."
        };
      }
    }

    return {
      ok: true,
      source: src,
      message: ""
    };
  },

  sourceNeedsVolume(src) {
    const sourceCategory = LotsInoculate.normalizeToken(src?.item_category_mat);

    return [
      "lcflask",
      "lcsyringe"
    ].includes(sourceCategory);
  },
  sourceLotUiError(sourceId) {
    const id = String(sourceId || "");
    const row = (qSourceLotsSearch.data || []).find(r =>
      String(r?.nocopk || "") === id
    );

    return String(row?.ui_error || "").trim();
  },

	canSubmitInoculate() {
	  const sourceCheck = LotsInoculate.sourceLotValidation();
	  const src = sourceCheck.source;
	  const targetCount = LotsInoculate.selectedLotIds().length;
	  const lcVolRaw = String(inpInocLCVolML.text || "").trim();
	  const lcVol = lcVolRaw === "" ? null : Number(lcVolRaw);
	  const storageLoc = LotsInoculate.selectedInocStorageLocationId();
	  const sourceRequiresVolume = LotsInoculate.sourceNeedsVolume(src);
	  const availableRaw = src?.remaining_volume_ml ?? src?.lc_volume_ml ?? src?.total_volume_ml;
	  const availableVolume = Number(availableRaw);
	  const requiredVolume = Number.isFinite(lcVol) ? lcVol * targetCount : NaN;
	  return appsmith.store.inoc_submitting !== true
	    && LotsInoculate.canOpenLotModal("inoculate")
	    && sourceCheck.ok
	    && Number.isFinite(Number(src?.nocopk))
	    && storageLoc !== null
	    && (!sourceRequiresVolume
	      || Number.isFinite(lcVol)
	        && lcVol > 0
	        && Number.isFinite(availableVolume)
	        && availableVolume > 0
	        && Number.isFinite(requiredVolume)
	        && requiredVolume <= availableVolume);
	},

  async verifyInoculateLots() {
    return LotsInoculate.validateAndWarnLotModal(
      "inoculate",
      "Select valid lots to inoculate."
    );
  },

  async openInoculateModal() {
    if (
      !LotsInoculate.validateAndWarnLotModal(
        "inoculate",
        "Select valid lots to inoculate."
      )
    ) {
      return;
    }

    txtInoculateContent.setText(LotsInoculate.formatSelectedLots());

    await Promise.allSettled([
      qSourceLotsSearch.run(),
      qInocLocations.run()
    ]);

		const defaultLoc = (qInocLocations.data || []).find(l =>
			String(l.name || "").trim().toLowerCase() === "dark room"
		) || (qInocLocations.data || [])[0];

		await selInoculateLocation.setSelectedOption(defaultLoc?.nocopk || "");

    await LotsInoculate.resetInoculateFormState();

    /*
      Standalone page note:
      No showModal(...) call is needed because the controls are already on the page.
    */
  },

	selectedInocStorageLocationId() {
		const locations = qInocLocations.data || [];
		const validIds = new Set(
			locations
				.map(l => Number(l.nocopk))
				.filter(id => Number.isFinite(id) && id > 0)
		);

		const selectedId = Number(selInoculateLocation.selectedOptionValue);
		if (Number.isFinite(selectedId) && validIds.has(selectedId)) {
			return selectedId;
		}

		/*
		  Appsmith may expose the label-based widget default before it resolves
		  the numeric option value. Fall back to the actual Dark Room row (or the
		  first valid inoculation location) so a visually defaulted location is
		  also valid for submission.
		*/
		const fallback = locations.find(l =>
			String(l.name || "").trim().toLowerCase() === "dark room"
		) || locations.find(l => validIds.has(Number(l.nocopk)));

		const fallbackId = Number(fallback?.nocopk);
		return Number.isFinite(fallbackId) && validIds.has(fallbackId)
			? fallbackId
			: null;
	},

  async resetInoculateFormState() {
    inpInocLCVolML.setValue("");
    inpInoculateNotes.setValue("");
    dpInoculateOverrideTime.setValue(null);
    resetWidget("tblInocSourceLots", false);
    await storeValue("inoc_source_id", null);
    await storeValue("inoc_target_ids", []);
    await storeValue("inoc_lc_vol", null);
    await storeValue("inoc_storage_loc", null);
    await storeValue("inoc_override_time", null);
    await storeValue("inoc_note", "");
    await storeValue("inoc_submitting", false);
  },

  async onInoculateContextChanged() {
    /*
      The standalone page allows source and target selections in either order.
      Do not clear visible form values when either table selection changes;
      doing so made the valid form appear complete while silently clearing the
      LC volume and leaving the submit button disabled. The submission snapshot
      is still invalidated and rebuilt immediately before qInoculateLots runs.
    */
    await storeValue("inoc_source_id", null);
    await storeValue("inoc_target_ids", []);
    await storeValue("inoc_lc_vol", null);
    await storeValue("inoc_storage_loc", null);
    await storeValue("inoc_override_time", null);
    await storeValue("inoc_note", "");
  },

  async inoculateSelectedLots() {
    const targetRows = LotsInoculate.selectedLotRows();
    const targetIds = targetRows
      .map(row => Number(row?.nocopk))
      .filter(Number.isFinite);

    if (!targetIds.length) {
      showAlert("No target lots selected.", "warning");
      return null;
    }
    if (!LotsInoculate.validateAndWarnLotModal("inoculate", "Select valid target lots to inoculate.")) {
      return null;
    }

    const sourceCheck = LotsInoculate.sourceLotValidation();
    if (!sourceCheck.ok) {
      showAlert(sourceCheck.message, "warning");
      return null;
    }

    const src = sourceCheck.source;
    const sourceId = Number(src?.nocopk);
    if (!Number.isFinite(sourceId)) {
      showAlert("Select a valid SOURCE lot in the Source Lots table.", "warning");
      return null;
    }

    const lcVolRaw = String(inpInocLCVolML.text || "").trim();
    const lcVol = lcVolRaw === "" ? null : Number(lcVolRaw);
    if (LotsInoculate.sourceNeedsVolume(src)) {
      const availableRaw = src.remaining_volume_ml ?? src.lc_volume_ml ?? src.total_volume_ml;
      const availableVolume = Number(availableRaw);
      const requiredVolume = Number.isFinite(lcVol) ? lcVol * targetIds.length : NaN;

      if (!Number.isFinite(lcVol) || lcVol <= 0) {
        showAlert("Enter a positive LC volume for this source lot.", "warning");
        return null;
      }
      if (!Number.isFinite(availableVolume) || availableVolume <= 0) {
        showAlert("Selected source lot has no remaining source volume.", "warning");
        return null;
      }
      if (!Number.isFinite(requiredVolume) || requiredVolume > availableVolume) {
        showAlert(`Not enough source volume for ${targetIds.length} target lot(s). Need ${requiredVolume} ml total, have ${availableVolume} ml.`, "warning");
        return null;
      }
    }

    const storageLoc = LotsInoculate.selectedInocStorageLocationId();
    if (storageLoc === null) {
      showAlert("Select a valid storage location.", "warning");
      return null;
    }

    const overrideTime =
      dpInoculateOverrideTime.isVisible && dpInoculateOverrideTime.selectedDate
        ? dpInoculateOverrideTime.selectedDate
        : null;

    if (overrideTime) {
      const overrideMoment = moment(overrideTime);
      const availabilityMoments = [
        src.created_at,
        src.sterilized_at,
        src.received_date,
        src.inoculated_at
      ]
        .filter(value => value !== undefined && value !== null && String(value).trim() !== "")
        .map(value => moment(value))
        .filter(value => value.isValid());

      if (overrideMoment.isValid() && availabilityMoments.length) {
        const sourceAvailableAt = moment.max(availabilityMoments);
        if (overrideMoment.isBefore(sourceAvailableAt)) {
          const sourceLabel = src.lot_id || sourceId;
          showAlert(
            `Override inoculation time ${overrideMoment.format("YYYY-MM-DD HH:mm")} cannot be before source lot ${sourceLabel} availability time ${sourceAvailableAt.format("YYYY-MM-DD HH:mm")}.`,
            "warning"
          );
          return null;
        }
      }
    }

    const notes = String(inpInoculateNotes.text || "").trim();

    await storeValue("inoc_source_id", sourceId);
    await storeValue("inoc_target_ids", targetIds);
    await storeValue(
      "inoc_lc_vol",
      LotsInoculate.sourceNeedsVolume(src) && Number.isFinite(lcVol) ? lcVol : null
    );
    await storeValue("inoc_storage_loc", storageLoc);
    await storeValue("inoc_override_time", overrideTime);
    await storeValue("inoc_note", notes);

    if (appsmith.store.inoc_submitting === true) return null;
    await storeValue("inoc_submitting", true);

    try {
      const res = await qInoculateLots.run();
      const inoculatedCount = Number(res?.[0]?.inoculated_count ?? 0);

      if (!Number.isFinite(inoculatedCount) || inoculatedCount <= 0) {
        const backendDiagnostic = String(res?.[0]?.diagnostic || "").trim();

        await Promise.allSettled([
          LotsInoculate.refresh(),
          qSourceLotsSearch.run()
        ]);

        const refreshedTargetIds = new Set(
          (qLots.data || [])
            .map(row => Number(row?.nocopk))
            .filter(Number.isFinite)
        );
        const ineligibleTargetLabels = targetRows
          .filter(row => !refreshedTargetIds.has(Number(row?.nocopk)))
          .map(row => row?.lot_id || row?.nocopk)
          .filter(value => value !== undefined && value !== null && String(value).trim() !== "");

        const refreshedSource = (qSourceLotsSearch.data || []).find(
          row => Number(row?.nocopk) === sourceId
        );

        const refreshedSourceError = LotsInoculate.sourceLotUiError(sourceId);

        let diagnostic = "";

        if (backendDiagnostic) {
          diagnostic = backendDiagnostic;
        } else if (refreshedSourceError) {
          diagnostic = refreshedSourceError;
        } else if (ineligibleTargetLabels.length) {
          diagnostic =
            `No lots were inoculated because target lot(s) ${ineligibleTargetLabels.join(", ")} are no longer eligible. Refresh Targets and select eligible, uninoculated lots.`;
        } else if (!refreshedSource) {
          diagnostic =
            `No lots were inoculated because source lot ${src?.lot_id || sourceId} is no longer eligible or has no usable remaining volume. Refresh Sources and select an available source.`;
        } else {
          diagnostic =
            "No lots were inoculated because the selected source or targets changed before submission. Refresh Sources and Targets, then try again.";
        }

        showAlert(diagnostic, "warning");
        resetWidget("tblInocSourceLots", false);
        return res;
      }

      await LotsInoculate.refresh();
      resetWidget("tblInocSourceLots", false);
      showAlert(`Inoculation of ${inoculatedCount} lot(s) complete.`, "success");
      return res;
    } catch (e) {
      const message = e?.message || String(e) || "Inoculation failed.";
      showAlert(message, "error");
      await storeValue("lots_error", message);
      return null;
    } finally {
      await storeValue("inoc_submitting", false);
    }
  },
};

