	harvestFreshTrayCount() {
	  const raw = inpHarvestFreshTrayCount.text;
	  const count = Number(
	    raw !== undefined && raw !== null && String(raw).trim() !== ""
	      ? raw
	      : 0
	  );
	  return Number.isFinite(count) && count > 0 ? count : 0;
	},


	harvestFrozenTrayCount() {
	  const raw = inpHarvestFrozenTrayCount.text;
	  const count = Number(
	    raw !== undefined && raw !== null && String(raw).trim() !== ""
	      ? raw
	      : 1
	  );
	  return Number.isFinite(count) && count > 0 ? count : 0;
	},


	async harvestSelectedLot() {
		if (!LotsHarvest.validateAndWarnLotModal("harvest", "Select exactly one active fruiting block lot to harvest.")) return;

		const weightG = Number(inpHarvestWeightG.text);
		const flushText = inpHarvestFlushNo.text;
		const flushNo = Number(
			flushText !== undefined && flushText !== null && String(flushText).trim() !== ""
				? flushText
				: (qHarvestFlushNo.data?.[0]?.next_flush_no ?? 1)
		);
		const freshTrayCount = LotsHarvest.harvestFreshTrayCount();
		const frozenTrayCount = LotsHarvest.harvestFrozenTrayCount();
		const totalTrayCount = freshTrayCount + frozenTrayCount;

		const freshLocationId = selHarvestFreshStorageLocation.selectedOptionValue
			|| LotsHarvest.defaultFreshHarvestLocationId();
		const frozenLocationId = selHarvestFrozeStorageLocation.selectedOptionValue
			|| LotsHarvest.defaultFrozenHarvestLocationId();

		const validFreshLocationIds = LotsHarvest.freshHarvestLocationOptions()
			.map(o => String(o.value));

		const validFrozenLocationIds = LotsHarvest.frozenHarvestLocationOptions()
			.map(o => String(o.value));

		if (!Number.isFinite(weightG) || weightG <= 0) {
			showAlert("Enter harvest weight in grams.", "warning");
			return;
		}

		if (!Number.isFinite(flushNo) || flushNo <= 0) {
			showAlert("Enter a valid flush number.", "warning");
			return;
		}

		if (totalTrayCount <= 0) {
			showAlert("Enter at least one fresh or freezer tray.", "warning");
			return;
		}

		if (
			freshTrayCount > 0
			&& (!freshLocationId || !validFreshLocationIds.includes(String(freshLocationId)))
		) {
			showAlert("Select a Fulfillment or product-ready destination for fresh harvest trays.", "warning");
			return;
		}

		if (
			frozenTrayCount > 0
			&& (!frozenLocationId || !validFrozenLocationIds.includes(String(frozenLocationId)))
		) {
			showAlert("Select a freezer/frozen destination for freezer tray harvest output.", "warning");
			return;
		}

		if (appsmith.store.harvest_submitting === true) return null;
		await storeValue("harvest_submitting", true);

		try {
			const res = await qHarvestLot.run();
			showAlert("Harvest created " + res[0].created_count + " tray product(s).", "success");
			/* standalone page: modal close not needed */
			await LotsHarvest.refresh();
			return res;
		} catch (e) {
			showAlert(e?.message || String(e), "error");
			return null;
		} finally {
			await storeValue("harvest_submitting", false);
		}
	}
};

