	},

	selectedLotIds() {
		return LotsDrawSyringes.selectedLotRows().map(r => r.nocopk).filter(Boolean);
	},

	formatSelectedLots() {
		const rows = LotsDrawSyringes.selectedLotRows();
		if (!rows.length) return "(No lots selected)";
		return rows.map(r => {
			const lotId = r.lot_id ?? r.nocopk;
			const inoc = r.inoculated_at ? moment(r.inoculated_at).format("YYYY-MM-DD") : "";
			const item = r.item_name_mat || "";
			const strain = r.strain_species_strain_mat || "";
			return `${lotId} | inoc:${inoc} | ${item} | ${strain}`.trim();
		}).join("\n");
	},

	lotIsRetired(row) {
		const status = String(row?.status || "").toLowerCase();
		return ["consumed", "expired", "retired", "compost", "composted", "compose"].some(s => status.includes(s));
	},

	lotModalValidation(actionOrOptions = {}) {
		const rows = LotsDrawSyringes.selectedLotRows();
		const action = typeof actionOrOptions === "string" ? actionOrOptions : null;
		const options = typeof actionOrOptions === "object" && actionOrOptions !== null ? actionOrOptions : {};

		const rulesByAction = {
			inoculate: {
				requireAny: true,
				allowedCategories: ["grain", "lc_flask", "plate", "cordyceps_substrate", "all_in_one_bag"],
				requireNoStrain: true,
				requireNotInoculated: true,
				message: "Select one or more active grain, LC flask, plate, cordyceps substrate, or all-in-one bag lots that have not already been inoculated or assigned a strain."
			},
			draw_syringes: {
				requireSingle: true,
				allowedCategories: ["lc_flask"],
				message: "Select exactly one active LC flask lot to draw syringes."
			},
			harvest: {
				requireSingle: true,
				allowedCategories: ["fruiting_block", "cordyceps_substrate", "all_in_one_bag"],
				message: "Select exactly one active fruiting block, cordyceps substrate, or all-in-one bag lot to harvest."
			}
		};

		const rules = {
			...(action ? (rulesByAction[action] || {}) : {}),
			...options
		};

		if (rules.requireSingle && rows.length !== 1) {
			return { ok: false, message: rules.message || "Select exactly one valid lot." };
		}

		if ((rules.requireAny || !rules.requireSingle) && rows.length === 0) {
			return { ok: false, message: rules.message || "Select one or more valid lots." };
		}

		for (const row of rows) {
			const label = row.lot_id || row.nocopk || "Selected lot";
			const category = String(row.item_category_mat || "");

			if (rules.allowedCategories && !rules.allowedCategories.includes(category)) {
				return { ok: false, message: `${label} has category ${category || "(blank)"}; expected ${rules.allowedCategories.join(", ")}.` };
			}

			if (!rules.allowRetired && LotsDrawSyringes.lotIsRetired(row)) {
				return { ok: false, message: `${label} is retired or unavailable (${row.status || "unknown status"}).` };
			}

			if (rules.requireNoStrain && row.strain_species_strain_mat) {
				return { ok: false, message: `${label} already has a strain (${row.strain_species_strain_mat}).` };
			}

			if (rules.requireNotInoculated && row.inoculated_at) {
				return { ok: false, message: `${label} was already inoculated (${row.inoculated_at}).` };
			}
		}

		return { ok: true, message: "" };
	},

	canOpenLotModal(actionOrOptions = {}) {
		return LotsDrawSyringes.lotModalValidation(actionOrOptions).ok;
	},

	validateAndWarnLotModal(actionOrOptions = {}, fallbackMessage = "Invalid lot selection for this action.") {
		const result = LotsDrawSyringes.lotModalValidation(actionOrOptions);
		if (!result.ok) {
			showAlert(result.message || fallbackMessage, "warning");
			return false;
		}

		return true;
	},

	async refresh() {
		await qLots.run();
		await qSyringeItems.run();
	},

	syringeItemOptions() {
		return (qSyringeItems.data || [])
			.filter(i => i && i.nocopk)
			.map(i => ({
				label: i.label || `${i.name || i.item_id || i.nocopk}`,
				value: i.nocopk,
				default_unit_size_ml: i.default_unit_size_ml
			}));
	},

	defaultSyringeItemId() {
		const opts = LotsDrawSyringes.syringeItemOptions();
		return opts[0]?.value || "";
	},

	selectedSyringeItem() {
		const selected = selSyringeItem.selectedOptionValue;
		return (qSyringeItems.data || [])
			.find(i => String(i.nocopk) === String(selected)) || null;
	},

	selectedFlaskLot() {
		return LotsDrawSyringes.selectedLotRows()[0] || null;
	},

	selectedFlaskRemainingMl() {
		const row = LotsDrawSyringes.selectedFlaskLot();
		const remaining = Number(row?.remaining_volume_ml);
		return Number.isFinite(remaining) ? remaining : 0;
	},

	requestedSyringeVolumeMl() {
		const count = Number(inpSyringeCount.text);
		const mlEach = Number(inpSyringeMlEach.text);

		if (!Number.isFinite(count) || !Number.isFinite(mlEach)) {
			return NaN;
		}

		return count * mlEach;
	},

	hasEnoughSelectedFlaskVolume() {
		const requested = LotsDrawSyringes.requestedSyringeVolumeMl();
		const remaining = LotsDrawSyringes.selectedFlaskRemainingMl();

		return Number.isFinite(requested)
			&& requested > 0
			&& remaining > 0
			&& requested <= remaining;
	},	

	canSubmitDrawSyringes() {
		const count = Number(inpSyringeCount.text);
		const mlEach = Number(inpSyringeMlEach.text);
		const selectedLocationId = selDrawSyringeLocation.selectedOptionValue;
		const validLocationIds = LotsDrawSyringes.drawSyringeLocationOptions()
			.map(o => String(o.value));

		const selectedSyringeItemId = selSyringeItem.selectedOptionValue;
		const validSyringeItemIds = LotsDrawSyringes.syringeItemOptions()
			.map(o => String(o.value));

		return LotsDrawSyringes.canOpenLotModal("draw_syringes")
			&& Number.isFinite(count)
			&& count > 0
			&& Number.isFinite(mlEach)
			&& mlEach > 0
			&& LotsDrawSyringes.hasEnoughSelectedFlaskVolume()
			&& !!selectedLocationId
			&& validLocationIds.includes(String(selectedLocationId))
			&& !!selectedSyringeItemId
			&& validSyringeItemIds.includes(String(selectedSyringeItemId));
	},

	drawSyringeLocationOptions() {
		const invalidNameParts = [
			"dark room",
			"fruiting",
			"shipping",
			"fulfillment",
			"products storage",
			"product storage",
			"lab",
			"shipped",
			"consumed",
			"compost",
			"expired"
		];

		return (qProductLocations.data || [])
			.filter(l => {
				const name = String(l.name || "").trim();
				const lower = name.toLowerCase();

				if (!name) return false;
				if (l.active === false) return false;

				const isRefrigerated =
					lower.includes("fridge") ||
					lower.includes("refrigerat");

				if (!isRefrigerated) return false;

				return !invalidNameParts.some(part => lower.includes(part));
			})
			.map(l => ({
				label: l.name,
				value: l.nocopk
			}));
	},

	defaultDrawSyringeLocationId() {
		const opts = LotsDrawSyringes.drawSyringeLocationOptions();

		const fridge = opts.find(o =>
			String(o.label || "").trim().toLowerCase() === "fridge"
		);

		return (fridge || opts[0])?.value || "";
	},

	async openDrawSyringesModal() {
		if (!LotsDrawSyringes.validateAndWarnLotModal("draw_syringes", "Select exactly one active LC flask lot first.")) return;

		inpSyringeCount.setValue("1");
		inpSyringeMlEach.setValue("10");
		inpDrawSyringesNotes.setValue("");

		await Promise.allSettled([
  		qProductLocations.run(),
  		qSyringeItems.run()
		]).finally(async () => {

			const defaultSyringeItemId = LotsDrawSyringes.defaultSyringeItemId();
			if (defaultSyringeItemId) {
				await selSyringeItem.setSelectedOption(defaultSyringeItemId);
			} else {
				await selSyringeItem.setSelectedOption("");
				showAlert("No active LC syringe item was found.", "warning");
			}

			const defaultLocationId = LotsDrawSyringes.defaultDrawSyringeLocationId();		
			if (defaultLocationId) {
				await selDrawSyringeLocation.setSelectedOption(defaultLocationId);
			} else {
				await selDrawSyringeLocation.setSelectedOption("");
				showAlert(
					"No refrigerated syringe storage location was found. Add or activate a Fridge/Refrigerated location before drawing syringes.",
					"warning"
				);
			}

			/* standalone page: modal open not needed */
		});
	},

	async drawSyringesFromSelectedFlask() {
	  const validation = LotsDrawSyringes.lotModalValidation("draw_syringes");
	  if (!validation.ok) {
	    showAlert(validation.message || "Select exactly one active LC flask lot first.", "warning");
	    return;
	  }
	  const count = Number(inpSyringeCount.text);
	  const mlEach = Number(inpSyringeMlEach.text);
	  const mode = selDrawSyringeOutputType.selectedOptionValue || "product";
	  const location = selDrawSyringeLocation.selectedOptionValue;
	  const validLocationIds = LotsDrawSyringes.drawSyringeLocationOptions().map(o => String(o.value));
	  if (!Number.isFinite(count) || count <= 0) {
	    showAlert("Enter a syringe count greater than 0.", "warning");
	    return;
	  }
	  if (!Number.isFinite(mlEach) || mlEach <= 0) {
	    showAlert("Enter mL per syringe greater than 0.", "warning");
	    return;
	  }
	  const requestedMl = count * mlEach;
	  const remainingMl = LotsDrawSyringes.selectedFlaskRemainingMl();
	  if (!Number.isFinite(remainingMl) || remainingMl <= 0) {
	    showAlert("Selected LC flask has no remaining volume.", "warning");
	    return;
	  }
	  if (requestedMl > remainingMl) {
	    showAlert(`Not enough LC volume. Need ${requestedMl} ml, have ${remainingMl} ml.`, "warning");
	    return;
	  }
	  if (!location || !validLocationIds.includes(String(location))) {
	    showAlert("Select a refrigerated Storage Location for drawn syringes.", "warning");
	    return;
	  }
	  try {
	    const res = mode === "product" ? await qDrawSyringeProducts.run() : await qDrawSyringes.run();
	    showAlert(mode === "product" ? "Syringe products created." : "Syringe lots created.", "success");

	    await Promise.allSettled([
	      resetWidget("inpSyringeCount", true),
	      resetWidget("inpSyringeMlEach", true),
	      resetWidget("inpDrawSyringesNotes", true),
	      resetWidget("selDrawSyringeOutputType", true),
	      resetWidget("inpStrains", true),
	      resetWidget("chkRegulated", true),
	      resetWidget("chkUnRegulated", true)
	    ]);

	    await LotsDrawSyringes.refresh();

	    await Promise.allSettled([
	      resetWidget("tblLots", true),
	      resetWidget("selSyringeItem", true),
	      resetWidget("selDrawSyringeLocation", true)
	    ]);

	    return res;
	  } catch (e) {
	    showAlert(e?.message || String(e), "error");
	    return null;
	  }
	}
};

variables.value:
{
  str(v) {
    if (v === undefined || v === null || v === "") return "NULL";
    return "'" + String(v).replace(/'/g, "''") + "'";
  },
  num(v) {
    const n = Number(v);
    return Number.isFinite(n) ? String(n) : "NULL";
  },
  arrBigint(arr) {
    if (!arr || arr.length === 0) return "ARRAY[]::bigint[]";
    const vals = arr.map(x => {
      const n = Number(x);
      return Number.isFinite(n) ? String(n) : "NULL";
    }).filter(x => x !== "NULL");
    if (vals.length === 0) return "ARRAY[]::bigint[]";
    return "ARRAY[" + vals.join(", ") + "]::bigint[]";
  }
}

