    const ids = (Array.isArray(values) ? values : []).map(Number).filter(Number.isFinite).map(Math.trunc);
    if (!ids.length) {
      return "ARRAY[]::bigint[]";
    }
    return `ARRAY[${[...new Set(ids)].join(",")}]::bigint[]`;
  }
}

publishedCollection.body:
export default {
  sql: {
    str(v) {
      if (v === undefined || v === null || v === "") return "NULL";
      return "'" + String(v).replace(/'/g, "''") + "'";
    },
    num(v) {
      const n = Number(v);
      return Number.isFinite(n) ? String(n) : "NULL";
    },
    arrBigint(arr) {
      if (!arr || arr.length === 0) return "ARRAY[]::bigint[]";
      const vals = arr
        .map(x => Number(x))
        .filter(Number.isFinite)
        .map(String);
      return vals.length ? "ARRAY[" + vals.join(", ") + "]::bigint[]" : "ARRAY[]::bigint[]";
    },
    bool(v) {
      return v === true ? "TRUE" : "FALSE";
    }
  },

  currentOperator() {
      const email = (appsmith.user?.email || "").trim().toLowerCase();
      const name = (appsmith.user?.name || "").trim();
      if (email) return email;
      if (name) return name;
      return "system";
  },

  locationOptions() {
      return (qReconLocations.data || []).map(row => ({
        label: row.name,
        value: row.nocopk
      }));
  },

  isSessionActive() {
      return appsmith.store.recon_active === true;
  },

  normalizeToken(value) {
      return String(value || "")
        .trim()
        .toLowerCase()
        .replace(/[^a-z0-9]/g, "");
  },

  normalizeProductNumber(raw) {
      const text = String(raw || "").trim();
      if (!text) return "";

      let decoded = text;
      try {
        decoded = decodeURIComponent(text);
      } catch (_) {
        decoded = text;
      }

      const match = decoded.match(/(?:PROD|LOT)-[A-Za-z0-9-]+/i);
      return match ? match[0] : decoded;
  },

  expectedRows() {
      const foundKeys = new Set(
        (appsmith.store.recon_found_rows || []).map(row =>
          String(row.entity_key || `${row.inventory_type || "Record"}:${row.nocopk}`)
        )
      );

      return (appsmith.store.recon_expected_rows || []).map(row => ({
        ...row,
        reconciliation_status: foundKeys.has(
          String(row.entity_key || `${row.inventory_type || "Record"}:${row.nocopk}`)
        ) ? "Found" : "Not found"
      }));
  },

  actionForFoundRow(row) {
      const targetId = String(appsmith.store.recon_location_id || "");
      const targetName = appsmith.store.recon_location_name || "selected location";
      const inventoryType = this.normalizeToken(row?.inventory_type);
      const location = this.normalizeToken(row?.storage_location);
      const trayState = this.normalizeToken(row?.tray_state);
      const lotStatus = this.normalizeToken(row?.status);
      const blockedLocations = ["consumed", "expired", "compost", "retired"];
      const blockedTrayStates = [
        "emptytray", "compost", "composted", "spoiled", "retired", "expired", "consumed", "shipped"
      ];
      const blockedLotStatuses = ["consumed", "retired", "expired", "compost", "composted"];

      if (blockedLocations.includes(location)) {
        return `BLOCKED: terminal location (${row?.storage_location || "unknown"})`;
      }

      if (inventoryType === "lot" && (blockedLotStatuses.includes(lotStatus) || location === "shipped")) {
        return `BLOCKED: terminal lot state (${row?.status || row?.storage_location || "unknown"})`;
      }

      if (inventoryType !== "lot" && blockedTrayStates.includes(trayState)) {
        return `BLOCKED: terminal product state (${row?.tray_state || "unknown"})`;
      }

      if (inventoryType !== "lot" && location === "shipped") {
        return "REVIEW: product currently recorded as Shipped";
      }

      if (String(row?.storage_location_id || "") === targetId) {
        return "Already correct";
      }

      if (location === "missingorlost") {
        return `Restore from Missing or Lost → ${targetName}`;
      }

      return `Move from ${row?.storage_location || "Unassigned"} → ${targetName}`;
  },

  foundRows() {
      return (appsmith.store.recon_found_rows || []).map(row => ({
        ...row,
        action: this.actionForFoundRow(row)
      }));
  },

  missingRows() {
      const foundKeys = new Set(
        (appsmith.store.recon_found_rows || []).map(row =>
          String(row.entity_key || `${row.inventory_type || "Record"}:${row.nocopk}`)
        )
      );
      return (appsmith.store.recon_expected_rows || []).filter(row =>
        !foundKeys.has(String(row.entity_key || `${row.inventory_type || "Record"}:${row.nocopk}`))
      );
  },

  changeRows() {
      if (!this.isSessionActive()) return [];

      const targetName = appsmith.store.recon_location_name || "selected location";
      const foundChanges = this.foundRows()
        .filter(row => row.action !== "Already correct")
        .map(row => ({
          inventory_type: row.inventory_type || "Record",
          inventory_id: row.inventory_id || row.product_id || row.lot_id || row.nocopk,
          action: row.action,
          from_location: row.storage_location || "Unassigned",
          to_location: targetName
        }));

      const missingChanges = this.missingRows().map(row => {
        const inventoryType = this.normalizeToken(row?.inventory_type);
        const trayState = this.normalizeToken(row?.tray_state);
        const lotStatus = this.normalizeToken(row?.status);
        const terminalProductStates = [
          "emptytray", "compost", "composted", "spoiled", "retired", "expired", "consumed", "shipped"
        ];
        const terminalLotStatuses = ["consumed", "retired", "expired", "compost", "composted"];
        const isTerminal = inventoryType === "lot"
          ? terminalLotStatuses.includes(lotStatus)
          : terminalProductStates.includes(trayState);

        return {
          inventory_type: row.inventory_type || "Record",
          inventory_id: row.inventory_id || row.product_id || row.lot_id || row.nocopk,
          action: isTerminal
            ? `SKIP: terminal ${inventoryType === "lot" ? "Lot" : "Product"} state`
            : "Move to Missing or Lost",
          from_location: targetName,
          to_location: isTerminal ? targetName : "Missing or Lost"
        };
      });

      return [...foundChanges, ...missingChanges];
  },

  blockedFoundRows() {
      return this.foundRows().filter(row => String(row.action || "").startsWith("BLOCKED:"));
  },

  shippedFoundRows() {
      return this.foundRows().filter(row => String(row.action || "").startsWith("REVIEW:"));
  },

  statusText() {
      if (!this.isSessionActive()) {
        return appsmith.store.recon_last_message ||
          "Select a physical storage location, then start a reconciliation. Products and Lots are counted together. No database changes occur until Finalize.";
      }

      const started = appsmith.store.recon_started_at
        ? new Date(appsmith.store.recon_started_at).toLocaleString()
        : "unknown time";
      const rows = appsmith.store.recon_expected_rows || [];
      const products = rows.filter(row => this.normalizeToken(row.inventory_type) === "product").length;
      const lots = rows.filter(row => this.normalizeToken(row.inventory_type) === "lot").length;
      return `Reconciling ${appsmith.store.recon_location_name || "selected location"} • started ${started} • ${rows.length} expected at start (${products} product${products === 1 ? "" : "s"}, ${lots} lot${lots === 1 ? "" : "s"}).`;
  },

  summaryText() {
      if (!this.isSessionActive()) return "No reconciliation session is active.";

      const expectedRows = appsmith.store.recon_expected_rows || [];
      const foundRows = appsmith.store.recon_found_rows || [];
      const expectedProducts = expectedRows.filter(row => this.normalizeToken(row.inventory_type) === "product").length;
      const expectedLots = expectedRows.filter(row => this.normalizeToken(row.inventory_type) === "lot").length;
      const foundProducts = foundRows.filter(row => this.normalizeToken(row.inventory_type) === "product").length;
      const foundLots = foundRows.filter(row => this.normalizeToken(row.inventory_type) === "lot").length;
      const missing = this.missingRows().length;
      const plannedMissing = this.changeRows().filter(row => row.action === "Move to Missing or Lost").length;
      const skippedTerminal = this.changeRows().filter(row => String(row.action || "").startsWith("SKIP:")).length;
      const alreadyCorrect = this.foundRows().filter(row => row.action === "Already correct").length;
      const shipped = this.shippedFoundRows().length;
      const blocked = this.blockedFoundRows().length;
      const movingIn = this.foundRows().filter(row =>
        row.action !== "Already correct" &&
        !String(row.action || "").startsWith("BLOCKED:")
      ).length;

      return `Expected: ${expectedRows.length} (${expectedProducts} products / ${expectedLots} lots) | Physically found: ${foundRows.length} (${foundProducts} products / ${foundLots} lots) | Not found: ${missing} | Planned Missing: ${plannedMissing} | Terminal skips: ${skippedTerminal} | Already correct: ${alreadyCorrect} | Move/restore in: ${movingIn} | Shipped product review: ${shipped} | Blocked: ${blocked}`;
  },

  finalizeSummary() {
      if (!this.isSessionActive()) return "No active reconciliation.";

      const foundRows = appsmith.store.recon_found_rows || [];
      const missingRows = this.missingRows();
      const plannedChanges = this.changeRows();
      const plannedMissingRows = plannedChanges.filter(row => row.action === "Move to Missing or Lost");
      const terminalSkips = plannedChanges.filter(row => String(row.action || "").startsWith("SKIP:"));
      const foundProducts = foundRows.filter(row => this.normalizeToken(row.inventory_type) === "product").length;
      const foundLots = foundRows.filter(row => this.normalizeToken(row.inventory_type) === "lot").length;
      const missingProducts = plannedMissingRows.filter(row => this.normalizeToken(row.inventory_type) === "product").length;
      const missingLots = plannedMissingRows.filter(row => this.normalizeToken(row.inventory_type) === "lot").length;
      const moveRows = this.foundRows().filter(row => row.action !== "Already correct");
      const shipped = this.shippedFoundRows().length;
      const alreadyCorrect = this.foundRows().filter(row => row.action === "Already correct").length;

      return [
        `Location: ${appsmith.store.recon_location_name || "selected location"}`,
        `Physically found: ${foundRows.length} (${foundProducts} products / ${foundLots} lots)`,
        `Already correct: ${alreadyCorrect}`,
        `Move/restore into location: ${moveRows.length}`,
        `Move to Missing or Lost: ${plannedMissingRows.length} (${missingProducts} products / ${missingLots} lots)`,
        `Terminal-state snapshot records that will be skipped: ${terminalSkips.length}`,
        `Shipped product corrections requiring audit notes: ${shipped}`,
        "",
        "Finalization is one PostgreSQL statement. Products or Lots that legitimately changed location after the starting snapshot are skipped rather than overwritten."
      ].join("\n");
  },

  canReview() {
      if (!this.isSessionActive() || appsmith.store.recon_submitting === true) return false;
      if (this.blockedFoundRows().length > 0) return false;

      const shippedCount = this.shippedFoundRows().length;
      if (shippedCount > 0 && !chkReconCorrectShipped.isChecked) return false;
      if (shippedCount > 0 && !String(inpReconNotes.text || "").trim()) return false;

      return true;
  },

  canFinalize() {
      if (!this.canReview()) return false;
      const plannedMissing = this.changeRows().filter(row => row.action === "Move to Missing or Lost").length;
      if (plannedMissing > 0 && !chkReconConfirmMissing.isChecked) return false;
      return true;
  },

  async startReconciliation() {
      if (this.isSessionActive()) {
        showAlert("A reconciliation is already active. Clear or finalize it before starting another.", "warning");
        return;
      }

      const locationId = Number(selReconLocation.selectedOptionValue);
      if (!Number.isFinite(locationId)) {
        showAlert("Select a physical storage location first.", "warning");
        return;
      }

      const locationName = String(selReconLocation.selectedOptionLabel || "").trim() ||
        String((qReconLocations.data || []).find(row => Number(row.nocopk) === locationId)?.name || "").trim();

      try {
        const rows = await qReconExpectedProducts.run({ location_id: locationId });
        await storeValue("recon_active", true);
        await storeValue("recon_location_id", locationId);
        await storeValue("recon_location_name", locationName || `Location ${locationId}`);
        await storeValue("recon_started_at", new Date().toISOString());
        await storeValue("recon_expected_rows", rows || []);
        await storeValue("recon_found_rows", []);
        await storeValue("recon_submitting", false);
        await storeValue("recon_last_message", "");
        await inpReconProductNumber.setValue("");
        await inpReconNotes.setValue("");
        await resetWidget("chkReconCorrectShipped", true);
        await resetWidget("chkReconConfirmMissing", true);
        await resetWidget("tblReconExpectedProducts", true);
        await resetWidget("tblReconFoundProducts", true);
        showAlert(`Reconciliation started for ${locationName || "selected location"}. Product and Lot changes are deferred until Finalize.`, "success");
      } catch (e) {
        showAlert(`Unable to start reconciliation: ${e?.message || String(e)}`, "error");
      }
  },

  async resetReconciliation() {
      await storeValue("recon_active", false);
      await storeValue("recon_location_id", "");
      await storeValue("recon_location_name", "");
      await storeValue("recon_started_at", "");
      await storeValue("recon_expected_rows", []);
      await storeValue("recon_found_rows", []);
      await storeValue("recon_submitting", false);
      await inpReconProductNumber.setValue("");
      await inpReconNotes.setValue("");
      await resetWidget("chkReconCorrectShipped", true);
      await resetWidget("chkReconConfirmMissing", true);
      await resetWidget("tblReconExpectedProducts", true);
      await resetWidget("tblReconFoundProducts", true);
      await selReconLocation.setSelectedOption("");
      closeModal(modalReconFinalize.name);
      showAlert("Reconciliation session cleared. No database inventory changes were made.", "info");
  },

  async addProduct(rawValue, fromScan) {
      const scanned = fromScan === true;
      if (!this.isSessionActive()) {
        showAlert(scanned ? "Start a reconciliation before scanning inventory." : "Start a reconciliation before adding inventory.", "warning");
        return;
      }

      const inputValue = scanned ? rawValue : inpReconProductNumber.text;
      const inventoryNumber = this.normalizeProductNumber(inputValue);
      if (!inventoryNumber) {
        showAlert(scanned ? "No Product or Lot identifier was detected in the scanned code." : "Enter a Product or Lot number.", "warning");
        return;
      }

      if (scanned && !/^(?:PROD|LOT)-[A-Za-z0-9-]+$/i.test(inventoryNumber)) {
        showAlert("Scanned code does not contain a valid Product or Lot identifier.", "warning");
        return;
      }

      const scanKey = inventoryNumber.toLowerCase();
      const now = Date.now();
      if (scanned) {
        const lastKey = String(appsmith.store.recon_last_scan_id || "");
        const lastAt = Number(appsmith.store.recon_last_scan_at || 0);
        const processingAt = Number(appsmith.store.recon_scan_processing_at || 0);
        const processing = appsmith.store.recon_scan_processing === true && now - processingAt < 5000;

        if (processing || (lastKey === scanKey && now - lastAt < 2000)) return;

        await storeValue("recon_scan_processing", true);
        await storeValue("recon_scan_processing_at", now);
        await storeValue("recon_last_scan_id", scanKey);
        await storeValue("recon_last_scan_at", now);
      }

      try {
        if (scanned) await inpReconProductNumber.setValue(inventoryNumber);

        const existing = (appsmith.store.recon_found_rows || []).find(row =>
          String(row.inventory_id || row.product_id || row.lot_id || "").toLowerCase() === inventoryNumber.toLowerCase()
        );
        if (existing) {
          await inpReconProductNumber.setValue("");
          showAlert(`${existing.inventory_type || "Inventory"} ${existing.inventory_id || inventoryNumber} is already in the physically found list.`, "info");
          return;
        }

        const rows = await qReconFindProduct.run({ product_code: inventoryNumber });
        if ((rows || []).length > 1) {
          showAlert(`More than one inventory record matched ${inventoryNumber}; resolve the duplicate identifier before reconciling it.`, "error");
          return;
        }
        const row = (rows || [])[0];
        if (!row) {
          showAlert(`Product or Lot not found: ${inventoryNumber}`, "error");
          return;
        }

        const foundRows = [...(appsmith.store.recon_found_rows || []), row];
        await storeValue("recon_found_rows", foundRows);
        await inpReconProductNumber.setValue("");
        await resetWidget("tblReconExpectedProducts", true);
        await resetWidget("tblReconFoundProducts", true);

        const action = this.actionForFoundRow(row);
        const displayId = row.inventory_id || row.product_id || row.lot_id || row.nocopk;
        if (String(action).startsWith("BLOCKED:")) {
          showAlert(`${row.inventory_type || "Inventory"} ${displayId}: ${action}`, "warning");
        } else if (String(action).startsWith("REVIEW:")) {
          showAlert(`${row.inventory_type || "Product"} ${displayId}: ${action}. Shipped correction and notes are required before finalizing.`, "warning");
        } else if (scanned) {
          showAlert(`${row.inventory_type || "Inventory"} ${displayId} scanned and added as physically found.`, "success");
        }
      } catch (e) {
        showAlert(`Unable to look up ${inventoryNumber}: ${e?.message || String(e)}`, "error");
      } finally {
        if (scanned) {
          await storeValue("recon_scan_processing", false);
          await storeValue("recon_scan_processing_at", 0);
        }
      }
  },

  async markSelectedFound() {
      if (!this.isSessionActive()) return;

      const selected = tblReconExpectedProducts.selectedRows || [];
      if (!selected.length) {
        showAlert("Select one or more expected inventory records first.", "warning");
        return;
      }

      const found = [...(appsmith.store.recon_found_rows || [])];
      const foundKeys = new Set(found.map(row =>
        String(row.entity_key || `${row.inventory_type || "Record"}:${row.nocopk}`)
      ));
      let added = 0;

      selected.forEach(row => {
        const key = String(row.entity_key || `${row.inventory_type || "Record"}:${row.nocopk}`);
        if (!foundKeys.has(key)) {
          const cleanRow = { ...row };
          delete cleanRow.reconciliation_status;
          found.push(cleanRow);
          foundKeys.add(key);
          added += 1;
        }
      });

      await storeValue("recon_found_rows", found);
      await resetWidget("tblReconExpectedProducts", true);
      await resetWidget("tblReconFoundProducts", true);
      showAlert(`${added} inventory record${added === 1 ? "" : "s"} marked physically found.`, "success");
  },

  async removeSelectedFound() {
      const selected = tblReconFoundProducts.selectedRows || [];
      if (!selected.length) {
        showAlert("Select one or more physically found inventory records to remove.", "warning");
        return;
      }

      const removeKeys = new Set(selected.map(row =>
        String(row.entity_key || `${row.inventory_type || "Record"}:${row.nocopk}`)
      ));
      const remaining = (appsmith.store.recon_found_rows || []).filter(row =>
        !removeKeys.has(String(row.entity_key || `${row.inventory_type || "Record"}:${row.nocopk}`))
      );

      await storeValue("recon_found_rows", remaining);
      await resetWidget("tblReconExpectedProducts", true);
      await resetWidget("tblReconFoundProducts", true);
      showAlert(`${selected.length} inventory record${selected.length === 1 ? "" : "s"} removed from the physically found list.`, "info");
  },

  async reviewFinalize() {
      if (!this.isSessionActive()) {
        showAlert("Start a reconciliation first.", "warning");
        return;
      }

      const blocked = this.blockedFoundRows();
      if (blocked.length) {
        showAlert(`Resolve ${blocked.length} blocked terminal-state inventory record${blocked.length === 1 ? "" : "s"} before finalizing.`, "error");
        return;
      }

      const shipped = this.shippedFoundRows();
      if (shipped.length && !chkReconCorrectShipped.isChecked) {
        showAlert("One or more physically found products are recorded as Shipped. Enable Shipped correction if this is intentional.", "warning");
        return;
      }

      if (shipped.length && !String(inpReconNotes.text || "").trim()) {
        showAlert("Enter reconciliation notes explaining the Shipped product correction before finalizing.", "warning");
        return;
      }

      await resetWidget("chkReconConfirmMissing", true);
      showModal(modalReconFinalize.name);
  },

  async finalizeReconciliation() {
      if (!this.canFinalize()) {
        showAlert("Review the reconciliation confirmation requirements before finalizing.", "warning");
        return;
      }

      if (appsmith.store.recon_submitting === true) return;
      await storeValue("recon_submitting", true);

      const expectedRows = appsmith.store.recon_expected_rows || [];
      const foundRows = appsmith.store.recon_found_rows || [];
      const idsFor = (rows, type) => rows
        .filter(row => this.normalizeToken(row.inventory_type) === type)
        .map(row => Number(row.nocopk))
        .filter(Number.isFinite);

      try {
        const rows = await qReconFinalize.run({
          location_id: Number(appsmith.store.recon_location_id),
          expected_product_ids: idsFor(expectedRows, "product"),
          found_product_ids: idsFor(foundRows, "product"),
          expected_lot_ids: idsFor(expectedRows, "lot"),
          found_lot_ids: idsFor(foundRows, "lot"),
          allow_shipped_correction: chkReconCorrectShipped.isChecked === true,
          operator: this.currentOperator(),
          notes: String(inpReconNotes.text || "").trim()
        });

        const result = (rows || [])[0] || {};
        const message = [
          `Reconciliation complete for ${result.target_location || appsmith.store.recon_location_name || "selected location"}.`,
          `${Number(result.moved_in_count || 0)} moved/restored into location,`,
          `${Number(result.marked_missing_count || 0)} moved to Missing or Lost,`,
          `${Number(result.skipped_expected_count || 0)} skipped because their state changed after the snapshot.`,
          `Processed ${Number(result.expected_product_count || 0)} expected products and ${Number(result.expected_lot_count || 0)} expected lots.`
        ].join(" ");

        await storeValue("recon_last_result", result);
        await storeValue("recon_last_message", message);
        closeModal(modalReconFinalize.name);

        await storeValue("recon_active", false);
        await storeValue("recon_location_id", "");
        await storeValue("recon_location_name", "");
        await storeValue("recon_started_at", "");
        await storeValue("recon_expected_rows", []);
        await storeValue("recon_found_rows", []);
        await inpReconProductNumber.setValue("");
        await inpReconNotes.setValue("");
        await resetWidget("chkReconCorrectShipped", true);
        await resetWidget("chkReconConfirmMissing", true);
        await resetWidget("tblReconExpectedProducts", true);
        await resetWidget("tblReconFoundProducts", true);
        await selReconLocation.setSelectedOption("");
        showAlert(message, Number(result.skipped_expected_count || 0) > 0 ? "warning" : "success");
      } catch (e) {
        showAlert(`Reconciliation failed; no partial Product or Lot changes were committed: ${e?.message || String(e)}`, "error");
      } finally {
        await storeValue("recon_submitting", false);
      }
  },
};

