export default {
  sql: {
    str(v) {
      if (v === undefined || v === null || v === "") return "NULL";
      return "'" + String(v).replace(/'/g, "''") + "'";
    },
    num(v) {
      const n = Number(v);
      return Number.isFinite(n) ? String(n) : "NULL";
    },
    bool(v) {
      return v === true ? "TRUE" : "FALSE";
    }
  },

  normalize(v) {
    return String(v || "").trim().toLowerCase();
  },

  activeFilterOptions() {
    return [
      { label: "All", value: "all" },
      { label: "Active", value: "active" },
      { label: "Inactive", value: "inactive" }
    ];
  },

  recipeCategoryOptions() {
    const base = ["agar", "casing", "cordyceps_substrate", "grain", "lc", "substrate"];
    const existing = (qRecipeAdminRecipes.data || [])
      .map(r => String(r.category || "").trim())
      .filter(Boolean);
    return [...new Set([...base, ...existing])]
      .sort((a, b) => a.localeCompare(b))
      .map(v => ({ label: v, value: v }));
  },

  ingredientCategoryOptions() {
    return [
      "grain", "substrate", "casing", "mineral", "nutrient",
      "supplement", "agar", "lc", "bulk", "water", "supply", "other"
    ].map(v => ({ label: v, value: v }));
  },

  unitOptions() {
    return ["g", "kg", "oz", "lb", "mL", "L", "tsp", "tbsp", "cup", "qt", "gal", "5-gal bucket", "each", "part"]
      .map(v => ({ label: v, value: v }));
  },

  roleOptions() {
    return ["primary", "grain", "substrate", "agar", "lc", "casing", "supplement", "other"]
      .map(v => ({ label: v, value: v }));
  },

  recipeOptions() {
    return (qRecipeAdminRecipes.data || [])
      .slice()
      .sort((a, b) => Number(b.active) - Number(a.active) || String(a.recipe_id || "").localeCompare(String(b.recipe_id || "")))
      .map(r => ({
        label: `${r.recipe_id || r.nocopk} — ${r.name || "Unnamed"}${r.active ? "" : " (inactive)"}`,
        value: r.nocopk
      }));
  },

  ingredientOptions() {
    return (qRecipeAdminIngredients.data || [])
      .slice()
      .sort((a, b) => Number(b.active) - Number(a.active) || String(a.name || "").localeCompare(String(b.name || "")))
      .map(i => ({
        label: `${i.ingredient_id || i.nocopk} — ${i.name || "Unnamed"}${i.active ? "" : " (inactive)"}`,
        value: i.nocopk
      }));
  },

  itemOptions() {
    return (qRecipeAdminItems.data || []).map(i => ({
      label: `${i.item_id || i.nocopk} — ${i.name || "Unnamed"}${i.active ? "" : " (inactive)"}`,
      value: i.nocopk
    }));
  },

  lotRecipeOptions() {
    const rows = qRecipeAdminLotComponents.data || [];
    const seen = new Map();
    rows.forEach(r => {
      if (r.recipe_nocopk && !seen.has(String(r.recipe_nocopk))) {
        seen.set(String(r.recipe_nocopk), {
          label: `${r.recipe_id || r.recipe_nocopk} — ${r.recipe_name || "Unnamed"}`,
          value: r.recipe_nocopk
        });
      }
    });
    return [{ label: "All Recipes", value: "all" }, ...Array.from(seen.values()).sort((a, b) => a.label.localeCompare(b.label))];
  },

  lotItemOptions() {
    const rows = qRecipeAdminLotComponents.data || [];
    const seen = new Map();
    rows.forEach(r => {
      if (r.item_nocopk && !seen.has(String(r.item_nocopk))) {
        seen.set(String(r.item_nocopk), {
          label: `${r.item_id || r.item_nocopk} — ${r.item_name || "Unnamed"}`,
          value: r.item_nocopk
        });
      }
    });
    return [{ label: "All Items", value: "all" }, ...Array.from(seen.values()).sort((a, b) => a.label.localeCompare(b.label))];
  },

  recipeRows() {
    const term = this.normalize(inpRecipeSearch.text);
    const status = String(selRecipeActiveFilter.selectedOptionValue || "all");
    return (qRecipeAdminRecipes.data || []).filter(r => {
      if (status === "active" && !r.active) return false;
      if (status === "inactive" && r.active) return false;
      if (!term) return true;
      return [r.recipe_id, r.name, r.category, r.ingredients, r.notes]
        .some(v => this.normalize(v).includes(term));
    });
  },

  ingredientRows() {
    const term = this.normalize(inpIngredientSearch.text);
    const status = String(selIngredientActiveFilter.selectedOptionValue || "all");
    return (qRecipeAdminIngredients.data || []).filter(i => {
      if (status === "active" && !i.active) return false;
      if (status === "inactive" && i.active) return false;
      if (!term) return true;
      return [i.ingredient_id, i.name, i.category, i.default_unit, i.preferred_vendor, i.notes]
        .some(v => this.normalize(v).includes(term));
    });
  },

  itemComponentRows() {
    const showInactive = chkRecipePlanShowInactive.isChecked === true;
    return (qRecipeAdminItemComponents.data || []).filter(r => showInactive || r.active === true);
  },

  lotComponentRows() {
    const term = this.normalize(inpLotComponentSearch.text);
    const recipeFilter = String(selLotComponentRecipeFilter.selectedOptionValue || "all");
    const itemFilter = String(selLotComponentItemFilter.selectedOptionValue || "all");
    return (qRecipeAdminLotComponents.data || []).filter(r => {
      if (recipeFilter !== "all" && String(r.recipe_nocopk || "") !== recipeFilter) return false;
      if (itemFilter !== "all" && String(r.item_nocopk || "") !== itemFilter) return false;
      if (!term) return true;
      return [
        r.lot_id, r.lot_recipe_component_id, r.item_id, r.item_name,
        r.recipe_id, r.recipe_name, r.source_component_id,
        r.component_role, r.notes
      ].some(v => this.normalize(v).includes(term));
    });
  },

  currentRecipe() {
    const id = Number(appsmith.store.recipe_admin_recipe_nocopk || 0);
    return (qRecipeAdminRecipes.data || []).find(r => Number(r.nocopk) === id) || null;
  },

  currentPlanItem() {
    const id = Number(appsmith.store.recipe_admin_plan_item_nocopk || selRecipePlanItem.selectedOptionValue || 0);
    return (qRecipeAdminItems.data || []).find(i => Number(i.nocopk) === id) || null;
  },

  legacyIngredientsText() {
    const r = this.currentRecipe();
    return r
      ? `Legacy Ingredients (read-only)\n${String(r.ingredients || "No legacy ingredient text recorded.")}`
      : "Legacy Ingredients (read-only)\nSelect a Recipe to view the imported legacy ingredient text.";
  },

  recipeIngredientsHeading() {
    const r = this.currentRecipe();
    return r ? `Structured Ingredients — ${r.recipe_id || r.name}` : "Structured Ingredients — select a Recipe";
  },

  planModeText() {
    const i = this.currentPlanItem();
    return `Component Mode: ${i?.component_mode || "—"}`;
  },

  planSizeText() {
    const i = this.currentPlanItem();
    return `Size Source: ${i?.size_source || "—"}`;
  },

  async refreshRecipes() {
    await qRecipeAdminRecipes.run();
    const recipeId = Number(appsmith.store.recipe_admin_recipe_nocopk || 0);
    if (recipeId > 0) await qRecipeAdminRecipeIngredients.run({ recipe_id: recipeId });
    showAlert("Recipes refreshed.", "success");
  },

  async newRecipe() {
    await storeValue("recipe_admin_recipe_nocopk", 0);
    await inpRecipeId.setValue("");
    await inpRecipeName.setValue("");
    await selRecipeCategory.setSelectedOption("");
    await chkRecipeActive.setValue(true);
    await txtRecipeNotes.setValue("");
    await qRecipeAdminRecipeIngredients.run({ recipe_id: 0 });
    await this.cancelRecipeIngredient();
  },

  async selectRecipe(row) {
    if (!row?.nocopk) return;
    await storeValue("recipe_admin_recipe_nocopk", Number(row.nocopk));
    await inpRecipeId.setValue(String(row.recipe_id || ""));
    await inpRecipeName.setValue(String(row.name || ""));
    await selRecipeCategory.setSelectedOption(String(row.category || ""));
    await chkRecipeActive.setValue(row.active === true);
    await txtRecipeNotes.setValue(String(row.notes || ""));
    await qRecipeAdminRecipeIngredients.run({ recipe_id: Number(row.nocopk) });
    await this.cancelRecipeIngredient();
  },

  async saveRecipe() {
    const recipeId = String(inpRecipeId.text || "").trim();
    const name = String(inpRecipeName.text || "").trim();
    if (!recipeId || !name) {
      showAlert("Recipe ID and Recipe Name are required.", "warning");
      return;
    }
    try {
      const rows = await qRecipeAdminSaveRecipe.run({
        nocopk: Number(appsmith.store.recipe_admin_recipe_nocopk || 0) || null,
        recipe_id: recipeId,
        name,
        category: selRecipeCategory.selectedOptionValue || null,
        active: chkRecipeActive.isChecked === true,
        notes: String(txtRecipeNotes.text || "").trim()
      });
      const saved = (rows || [])[0];
      await qRecipeAdminRecipes.run();
      if (saved?.nocopk) {
        const refreshed = (qRecipeAdminRecipes.data || []).find(r => Number(r.nocopk) === Number(saved.nocopk)) || saved;
        await this.selectRecipe(refreshed);
      }
      showAlert(`Recipe ${saved?.recipe_id || recipeId} saved.`, "success");
    } catch (e) {
      showAlert(`Unable to save Recipe: ${e?.message || String(e)}`, "error");
    }
  },

  async cancelRecipe() {
    const current = this.currentRecipe();
    if (current) return this.selectRecipe(current);
    return this.newRecipe();
  },

  async newRecipeIngredient() {
    if (!Number(appsmith.store.recipe_admin_recipe_nocopk || 0)) {
      showAlert("Select or save a Recipe before adding structured ingredients.", "warning");
      return;
    }
    await storeValue("recipe_admin_recipe_ingredient_nocopk", 0);
    await selRecipeIngredient.setSelectedOption("");
    await inpRecipeIngredientAmount.setValue("");
    await selRecipeIngredientUnit.setSelectedOption("");
    await inpRecipeIngredientVendor.setValue("");
    await inpRecipeIngredientSortOrder.setValue("");
    await chkRecipeIngredientActive.setValue(true);
    await txtRecipeIngredientNotes.setValue("");
  },

  async selectRecipeIngredient(row) {
    if (!row?.nocopk) return;
    await storeValue("recipe_admin_recipe_ingredient_nocopk", Number(row.nocopk));
    await selRecipeIngredient.setSelectedOption(String(row.ingredient_nocopk || row.ingredient_id || ""));
    await inpRecipeIngredientAmount.setValue(row.amount == null ? "" : String(row.amount));
    await selRecipeIngredientUnit.setSelectedOption(String(row.unit || row.ingredient_default_unit || ""));
    await inpRecipeIngredientVendor.setValue(String(row.vendor_name || row.ingredient_preferred_vendor || ""));
    await inpRecipeIngredientSortOrder.setValue(row.sort_order == null ? "" : String(row.sort_order));
    await chkRecipeIngredientActive.setValue(row.active === true);
    await txtRecipeIngredientNotes.setValue(String(row.notes || ""));
  },

  async saveRecipeIngredient() {
    const recipePk = Number(appsmith.store.recipe_admin_recipe_nocopk || 0);
    const ingredientPk = Number(selRecipeIngredient.selectedOptionValue || 0);
    const amount = Number(inpRecipeIngredientAmount.text);
    const unit = String(selRecipeIngredientUnit.selectedOptionValue || "").trim();
    if (!recipePk || !ingredientPk || !Number.isFinite(amount) || amount <= 0 || !unit) {
      showAlert("Recipe, Ingredient, positive Amount, and Unit are required.", "warning");
      return;
    }
    try {
      await qRecipeAdminSaveRecipeIngredient.run({
        nocopk: Number(appsmith.store.recipe_admin_recipe_ingredient_nocopk || 0) || null,
        recipe_id: recipePk,
        ingredient_id: ingredientPk,
        amount,
        unit,
        vendor_name: String(inpRecipeIngredientVendor.text || "").trim(),
        sort_order: String(inpRecipeIngredientSortOrder.text || "").trim() === "" ? null : Number(inpRecipeIngredientSortOrder.text),
        active: chkRecipeIngredientActive.isChecked === true,
        notes: String(txtRecipeIngredientNotes.text || "").trim()
      });
      await qRecipeAdminRecipeIngredients.run({ recipe_id: recipePk });
      await qRecipeAdminRecipes.run();
      await this.newRecipeIngredient();
      showAlert("Structured Recipe Ingredient saved.", "success");
    } catch (e) {
      showAlert(`Unable to save Recipe Ingredient: ${e?.message || String(e)}`, "error");
    }
  },

  async cancelRecipeIngredient() {
    await storeValue("recipe_admin_recipe_ingredient_nocopk", 0);
    await selRecipeIngredient.setSelectedOption("");
    await inpRecipeIngredientAmount.setValue("");
    await selRecipeIngredientUnit.setSelectedOption("");
    await inpRecipeIngredientVendor.setValue("");
    await inpRecipeIngredientSortOrder.setValue("");
    await chkRecipeIngredientActive.setValue(true);
    await txtRecipeIngredientNotes.setValue("");
  },

  async refreshIngredients() {
    await qRecipeAdminIngredients.run();
    showAlert("Ingredients refreshed.", "success");
  },

  async newIngredient() {
    await storeValue("recipe_admin_ingredient_nocopk", 0);
    await inpIngredientId.setValue("");
    await inpIngredientName.setValue("");
    await selIngredientCategory.setSelectedOption("");
    await selIngredientDefaultUnit.setSelectedOption("");
    await inpIngredientPreferredVendor.setValue("");
    await chkIngredientActive.setValue(true);
    await txtIngredientNotes.setValue("");
  },

  async selectIngredient(row) {
    if (!row?.nocopk) return;
    await storeValue("recipe_admin_ingredient_nocopk", Number(row.nocopk));
    await inpIngredientId.setValue(String(row.ingredient_id || ""));
    await inpIngredientName.setValue(String(row.name || ""));
    await selIngredientCategory.setSelectedOption(String(row.category || ""));
    await selIngredientDefaultUnit.setSelectedOption(String(row.default_unit || ""));
    await inpIngredientPreferredVendor.setValue(String(row.preferred_vendor || ""));
    await chkIngredientActive.setValue(row.active === true);
    await txtIngredientNotes.setValue(String(row.notes || ""));
  },

  async saveIngredient() {
    const ingredientId = String(inpIngredientId.text || "").trim();
    const name = String(inpIngredientName.text || "").trim();
    if (!ingredientId || !name) {
      showAlert("Ingredient ID and Ingredient Name are required.", "warning");
      return;
    }
    try {
      const rows = await qRecipeAdminSaveIngredient.run({
        nocopk: Number(appsmith.store.recipe_admin_ingredient_nocopk || 0) || null,
        ingredient_id: ingredientId,
        name,
        category: selIngredientCategory.selectedOptionValue || null,
        default_unit: selIngredientDefaultUnit.selectedOptionValue || null,
        preferred_vendor: String(inpIngredientPreferredVendor.text || "").trim(),
        active: chkIngredientActive.isChecked === true,
        notes: String(txtIngredientNotes.text || "").trim()
      });
      const saved = (rows || [])[0];
      await qRecipeAdminIngredients.run();
      if (saved?.nocopk) {
        const refreshed = (qRecipeAdminIngredients.data || []).find(i => Number(i.nocopk) === Number(saved.nocopk)) || saved;
        await this.selectIngredient(refreshed);
      }
      showAlert(`Ingredient ${saved?.ingredient_id || ingredientId} saved.`, "success");
    } catch (e) {
      showAlert(`Unable to save Ingredient: ${e?.message || String(e)}`, "error");
    }
  },

  async cancelIngredient() {
    const id = Number(appsmith.store.recipe_admin_ingredient_nocopk || 0);
    const current = (qRecipeAdminIngredients.data || []).find(i => Number(i.nocopk) === id);
    if (current) return this.selectIngredient(current);
    return this.newIngredient();
  },

  async selectPlanItem() {
    const itemPk = Number(selRecipePlanItem.selectedOptionValue || 0);
    await storeValue("recipe_admin_plan_item_nocopk", itemPk || 0);
    await qRecipeAdminItemComponents.run({ item_id: itemPk || 0 });
    await this.cancelItemComponent();
  },

  async refreshPlan() {
    await qRecipeAdminItems.run();
    await qRecipeAdminRecipes.run();
    await this.selectPlanItem();
    showAlert("Item component plan refreshed.", "success");
  },

  async newItemComponent() {
    const item = this.currentPlanItem();
    if (!item?.nocopk) {
      showAlert("Select an Item before adding a component.", "warning");
      return;
    }
    const mode = String(item.component_mode || "none").toLowerCase();
    if (!["single_recipe", "multi_recipe"].includes(mode)) {
      showAlert("The selected Item does not use Recipe Components.", "warning");
      return;
    }
    await storeValue("recipe_admin_item_component_nocopk", 0);
    await chkRecipePlanComponentActive.setValue(true);
    await inpRecipePlanComponentSet.setValue("");
    await selRecipePlanRecipe.setSelectedOption("");
    await selRecipePlanComponentRole.setSelectedOption("");
    await inpRecipePlanUnitSizeLb.setValue("");
    await inpRecipePlanDefaultWeightLb.setValue("");
    await inpRecipePlanDefaultPercent.setValue("");
    await inpRecipePlanSortOrder.setValue("");
    await txtRecipePlanComponentNotes.setValue("");
  },

  async selectItemComponent(row) {
    if (!row?.nocopk) return;
    await storeValue("recipe_admin_item_component_nocopk", Number(row.nocopk));
    await chkRecipePlanComponentActive.setValue(row.active === true);
    await inpRecipePlanComponentSet.setValue(String(row.component_set || ""));
    await selRecipePlanRecipe.setSelectedOption(String(row.recipe_nocopk || row.recipe_id || ""));
    await selRecipePlanComponentRole.setSelectedOption(String(row.component_role || ""));
    await inpRecipePlanUnitSizeLb.setValue(row.unit_size_lb == null ? "" : String(row.unit_size_lb));
    await inpRecipePlanDefaultWeightLb.setValue(row.default_weight_lb == null ? "" : String(row.default_weight_lb));
    await inpRecipePlanDefaultPercent.setValue(row.default_percent == null ? "" : String(row.default_percent));
    await inpRecipePlanSortOrder.setValue(row.sort_order == null ? "" : String(row.sort_order));
    await txtRecipePlanComponentNotes.setValue(String(row.notes || ""));
  },

  async saveItemComponent() {
    const item = this.currentPlanItem();
    const recipePk = Number(selRecipePlanRecipe.selectedOptionValue || 0);
    const role = String(selRecipePlanComponentRole.selectedOptionValue || "").trim();
    if (!item?.nocopk || !recipePk || !role) {
      showAlert("Item, Recipe, and Component Role are required.", "warning");
      return;
    }
    const mode = String(item.component_mode || "none").toLowerCase();
    if (!["single_recipe", "multi_recipe"].includes(mode)) {
      showAlert("The selected Item does not use Recipe Components.", "warning");
      return;
    }
    if (mode === "multi_recipe" && !String(inpRecipePlanComponentSet.text || "").trim()) {
      showAlert("Component Set is required for multi-recipe Items.", "warning");
      return;
    }
    const optNum = value => String(value ?? "").trim() === "" ? null : Number(value);
    try {
      await qRecipeAdminSaveItemComponent.run({
        nocopk: Number(appsmith.store.recipe_admin_item_component_nocopk || 0) || null,
        item_id: Number(item.nocopk),
        component_set: String(inpRecipePlanComponentSet.text || "").trim(),
        recipe_id: recipePk,
        component_role: role,
        unit_size_lb: optNum(inpRecipePlanUnitSizeLb.text),
        default_weight_lb: optNum(inpRecipePlanDefaultWeightLb.text),
        default_percent: optNum(inpRecipePlanDefaultPercent.text),
        sort_order: optNum(inpRecipePlanSortOrder.text),
        active: chkRecipePlanComponentActive.isChecked === true,
        notes: String(txtRecipePlanComponentNotes.text || "").trim()
      });
      await qRecipeAdminItemComponents.run({ item_id: Number(item.nocopk) });
      await this.newItemComponent();
      showAlert("Item Recipe Component saved.", "success");
    } catch (e) {
      showAlert(`Unable to save Item Recipe Component: ${e?.message || String(e)}`, "error");
    }
  },

  async cancelItemComponent() {
    await storeValue("recipe_admin_item_component_nocopk", 0);
    await chkRecipePlanComponentActive.setValue(true);
    await inpRecipePlanComponentSet.setValue("");
    await selRecipePlanRecipe.setSelectedOption("");
    await selRecipePlanComponentRole.setSelectedOption("");
    await inpRecipePlanUnitSizeLb.setValue("");
    await inpRecipePlanDefaultWeightLb.setValue("");
    await inpRecipePlanDefaultPercent.setValue("");
    await inpRecipePlanSortOrder.setValue("");
    await txtRecipePlanComponentNotes.setValue("");
  },

  async refreshLotComponents() {
    await qRecipeAdminLotComponents.run();
    showAlert("Lot component history refreshed.", "success");
  }
};

