function ({show = true} = {}) {
  const errs = [];
  if (!selProcessType.selectedOptionValue) {
    errs.push("Select a process type.");
  }
  if (!selPlannedItem.selectedOptionValue) {
    errs.push("Select a planned item.");
  }
  const selectedItem = (qItems.data || []).find(i => String(i.nocopk) === String(selPlannedItem.selectedOptionValue));
  const componentMode = String(selectedItem?.component_mode || "single_recipe").trim().toLowerCase();
  if (!selPlannedRecipe.selectedOptionValue) {
    errs.push(componentMode === "multi_recipe" ? "Select a component set for this multi-recipe item." : "Select a planned recipe for this single-recipe item.");
  }
  const unit = Number(inpPlannedUnitSize.text);
  const cnt = Number(inpPlannedCount.text);
  if (!Number.isFinite(unit) || unit <= 0) {
    errs.push("Planned unit size must be > 0.");
  }
  if (!Number.isFinite(cnt) || cnt <= 0) {
    errs.push("Planned count must be > 0.");
  }
  if (show) {
    errs.forEach(msg => showAlert(msg, "error"));
  }
  return errs;
}

