async function () {
  if (ProductsPage.isRetireTraySubmitting()) {
    return;
  }
  if (!ProductsPage.canSubmitRetireTray()) {
    showAlert("Select active tray products and a reason.", "warning");
    return;
  }
  await storeValue("products_retire_tray_submitting", true);
  try {
    const affectedCount = ProductsPage.selectedProductIds().length;
    const reason = String(selRetireTrayReason.selectedOptionValue || "").toLowerCase();
    const actionLabel = ({
      spoiled: "marked Spoiled",
      compost: "marked Compost",
      retired: "marked Retired"
    })[reason] || "updated";
    const res = await qRetireTrayProducts.run();
    showAlert(`${affectedCount} tray product${affectedCount === 1 ? "" : "s"} ${actionLabel}.`, "success");
    closeModal(modalRetireTray.name);
    await ProductsPage.refresh();
    return res;
  } catch (e) {
    showAlert(e?.message || String(e), "error");
    return null;
  } finally {
    await storeValue("products_retire_tray_submitting", false);
  }
}

