function (value = selPkgFDSizeG.selectedOptionValue) {
  const sizeG = Number(value);
  if (!Number.isFinite(sizeG) || sizeG <= 0) return null;
  if (Math.abs(sizeG - 1) <= 0.01) return 1;
  if (Math.abs(sizeG - 5) <= 0.01) return 5;
  if (Math.abs(sizeG - 10) <= 0.01) return 10;
  if (Math.abs(sizeG - 28.349523125) <= 0.02) return 28.349523125;
  return null;
}

