async function () {
  if (ProductsPage.isPackageFreezeDriedSubmitting()) {
    return;
  }
  const normalizedSizeG = ProductsPage.freezeDriedPackageItemSizeG();
  if (!normalizedSizeG) {
    showAlert("Package size must be 1 g, 5 g, 10 g, or 1 oz (28.35 g).", "warning");
    return;
  }
  if (!ProductsPage.canSubmitPackageFreezeDried()) {
    showAlert("Select enough active freezer tray product weight and complete the package form.", "warning");
    return;
  }
  const request = ProductsPage.freezeDriedPackageRequest();
  await storeValue("products_package_fd_submitting", true);
  try {
    const requestedCount = request.package_count;
    const res = await qPackageFreezeDried.run(request);
    showAlert(`${requestedCount} freeze-dried package${requestedCount === 1 ? "" : "s"} created.`, "success");
    closeModal(modalPackageFreezeDried.name);
    await ProductsPage.refresh();
    return res;
  } catch (e) {
    showAlert(e?.message || String(e), "error");
    return null;
  } finally {
    await storeValue("products_package_fd_submitting", false);
  }
}

