function () {
  const locations = qInocLocations.data || [];
  const validIds = new Set(locations.map(l => Number(l.nocopk)).filter(id => Number.isFinite(id) && id > 0));
  const selectedId = Number(selInoculateLocation.selectedOptionValue);
  if (Number.isFinite(selectedId) && validIds.has(selectedId)) {
    return selectedId;
  }
  const fallback = locations.find(l => String(l.name || "").trim().toLowerCase() === "dark room") || locations.find(l => validIds.has(Number(l.nocopk)));
  const fallbackId = Number(fallback?.nocopk);
  return Number.isFinite(fallbackId) && validIds.has(fallbackId) ? fallbackId : null;
}

