actionConfiguration.body:
function () {
  const src = LotsInoculate.selectedInocSourceLot();
  if (!src) {
    return {
      ok: false,
      source: null,
      message: "Select a valid SOURCE lot from the current Source Lots table."
    };
  }
  const normalize = LotsInoculate.normalizeCategory || LotsInoculate.normalizeToken;
  const sourceCategory = normalize(src.item_category_mat);
  const sourceStatus = normalize(src.status);
  const allowedSourceCategories = ["grain", "lcflask", "lcsyringe", "plate", "agarplate", "untrackedsource"];
  const allowedSourceStatuses = ["inoculated", "colonizing", "fullycolonized", "fridge", "coldshock"];
  const terminalStatuses = ["consumed", "expired", "retired", "compost", "composted", "deleted"];
  if (!allowedSourceCategories.includes(sourceCategory)) {
    return {
      ok: false,
      source: src,
      message: `Selected source lot has invalid category: ${src.item_category_mat || "(blank)"}.`
    };
  }
  if (terminalStatuses.includes(sourceStatus)) {
    return {
      ok: false,
      source: src,
      message: `Selected source lot is not available for inoculation. Status: ${src.status || "(blank)"}.`
    };
  }
  if (!allowedSourceStatuses.includes(sourceStatus)) {
    return {
      ok: false,
      source: src,
      message: `Selected source lot is not available for inoculation. Status: ${src.status || "(blank)"}.`
    };
  }
  if (LotsInoculate.sourceNeedsVolume(src)) {
    const availableRaw = src.remaining_volume_ml ?? src.lc_volume_ml ?? src.total_volume_ml;
    const available = Number(availableRaw);
    if (!Number.isFinite(available) || available <= 0) {
      return {
        ok: false,
        source: src,
        message: "Selected source lot has no remaining source volume."
      };
    }
  }
  return {
    ok: true,
    source: src,
    message: ""
  };
}

