    if (!name) return false;
    if (l.active === false) return false;
    if (invalidNameParts.some(part => lower.includes(part))) return false;
    return lower.includes("fulfillment") || lower.includes("product-ready") || lower.includes("product ready") || lower.includes("products storage") || lower.includes("product storage");
  }).map(l => ({
    label: l.name,
    value: l.nocopk
  }));
}

