async function (newStatus, clearError) {
  const ids = PrintQueuePage.selectedIds();
  const reason = String(inpPQStatusReason.text || "").trim();
  if (!ids.length) {
    showAlert("Select at least one print job.", "warning");
    return null;
  }
  if (PrintQueuePage.hasPrintingSelection()) {
    showAlert("A job currently marked Printing cannot be changed or requeued.", "error");
    return null;
  }
  if (["Queued", "Error"].includes(String(newStatus || "")) && !reason) {
    showAlert(`Enter a reason before changing print jobs to ${newStatus}.`, "warning");
    return null;
  }
  const extractUpdatedCount = value => {
    if (Array.isArray(value)) {
      for (const entry of value) {
        const found = extractUpdatedCount(entry);
        if (Number.isFinite(found)) return found;
      }
      return null;
    }
    if (!value || typeof value !== "object") return null;
    const direct = Number(value.updated_count ?? value.mp_print_queue_set_status);
    if (Number.isFinite(direct)) return direct;
    for (const entry of Object.values(value)) {
      const found = extractUpdatedCount(entry);
      if (Number.isFinite(found)) return found;
    }
    return null;
  };
  try {
    const result = await qPQSetStatus.run({
      print_queue_ids: ids,
      new_status: newStatus,
      clear_error: clearError === true,
      reason,
      operator: PrintQueuePage.currentOperator()
    });
    const returnedCount = extractUpdatedCount(result) ?? extractUpdatedCount(qPQSetStatus.data);
    const updatedCount = Number.isFinite(returnedCount) && returnedCount > 0 ? returnedCount : ids.length;
    showAlert(`${updatedCount} print job(s) changed to ${newStatus}.`, "success");
    await Promise.allSettled([resetWidget("selPQNewStatus", true), resetWidget("inpPQStatusReason", true), resetWidget("tblPrintQueue", true)]);
    await qPrintQueue.run();
    return result;
  } catch (error) {
    showAlert(error?.message || String(error), "error");
    return null;
  }
}

