SELECT
  v.nocopk,
  v.print_id,
  v.source_kind,
  v.print_status,
  v.label_type,
  v.print_target,
  v.lot_id,
  l.lot_id AS lot_ref,
  v.product_id,
  p.product_id AS product_ref,
  v.run_id,
  sr.steri_run_id AS run_ref,
  v.created_at,
  v.claimed_by,
  v.claimed_at,
  v.printed_by,
  v.printed_at,
  v.error_msg,
  v.pdf_path
FROM public.vc_print_queue v
LEFT JOIN public.lots l ON l.nocopk = v.lot_id
LEFT JOIN public.products p ON p.nocopk = v.product_id
LEFT JOIN public.sterilization_runs sr ON sr.nocopk = v.run_id
WHERE
  (
    {{ PrintQueuePage.sql.bool(String(selPQStatus.selectedOptionValue || "ALL") === "ALL") }}
    OR v.print_status = {{ PrintQueuePage.sql.str(selPQStatus.selectedOptionValue || "ALL") }}
  )
  AND (
    {{ PrintQueuePage.sql.bool(String(selPQTarget.selectedOptionValue || "ALL") === "ALL") }}
    OR v.print_target = {{ PrintQueuePage.sql.str(selPQTarget.selectedOptionValue || "ALL") }}
  )
  AND (
    {{ PrintQueuePage.sql.bool(String(selPQSourceKind.selectedOptionValue || "ALL") === "ALL") }}
    OR v.source_kind = {{ PrintQueuePage.sql.str(selPQSourceKind.selectedOptionValue || "ALL") }}
  )
  AND (
    {{ PrintQueuePage.sql.bool(String(selPQLabelType.selectedOptionValue || "ALL") === "ALL") }}
    OR v.label_type = {{ PrintQueuePage.sql.str(selPQLabelType.selectedOptionValue || "ALL") }}
  )
  AND (
    {{ PrintQueuePage.sql.bool(!String(inpPQClaimedBy.text || "").trim()) }}
    OR COALESCE(v.claimed_by, '') ILIKE '%' || {{ PrintQueuePage.sql.str(inpPQClaimedBy.text) }} || '%'
  )
  AND (
    {{ PrintQueuePage.sql.bool(!chkPQErrorsOnly.isChecked) }}
    OR v.print_status = 'Error'
  )
  AND (
    {{ PrintQueuePage.sql.bool(!dpPQCreatedFrom.selectedDate) }}
    OR v.created_at >= {{ PrintQueuePage.sql.str(dpPQCreatedFrom.selectedDate || "") }}::date
  )
  AND (
    {{ PrintQueuePage.sql.bool(!dpPQCreatedTo.selectedDate) }}
    OR v.created_at < ({{ PrintQueuePage.sql.str(dpPQCreatedTo.selectedDate || "") }}::date + INTERVAL '1 day')
  )
  AND (
    {{ PrintQueuePage.sql.bool(!String(inpPQSearch.text || "").trim()) }}
    OR CONCAT_WS(
      ' ',
      v.print_id,
      v.print_status,
      v.print_target,
      v.source_kind,
      v.label_type,
      l.lot_id,
      p.product_id,
      sr.steri_run_id,
      v.claimed_by,
      v.printed_by,
      v.error_msg,
      v.pdf_path
    ) ILIKE '%' || {{ PrintQueuePage.sql.str(inpPQSearch.text) }} || '%'
  )
ORDER BY v.created_at DESC NULLS LAST, v.nocopk DESC
LIMIT 500;

