actionConfiguration.body:
function (row) {
  const targetId = String(appsmith.store.recon_location_id || "");
  const targetName = appsmith.store.recon_location_name || "selected location";
  const inventoryType = InventoryReconcile.normalizeToken(row?.inventory_type);
  const location = InventoryReconcile.normalizeToken(row?.storage_location);
  const trayState = InventoryReconcile.normalizeToken(row?.tray_state);
  const lotStatus = InventoryReconcile.normalizeToken(row?.status);
  const blockedLocations = ["consumed", "expired", "compost", "retired"];
  const blockedTrayStates = ["emptytray", "compost", "composted", "spoiled", "retired", "expired", "consumed", "shipped"];
  const blockedLotStatuses = ["consumed", "retired", "expired", "compost", "composted"];
  if (blockedLocations.includes(location)) {
    return `BLOCKED: terminal location (${row?.storage_location || "unknown"})`;
  }
  if (inventoryType === "lot" && (blockedLotStatuses.includes(lotStatus) || location === "shipped")) {
    return `BLOCKED: terminal lot state (${row?.status || row?.storage_location || "unknown"})`;
  }
  if (inventoryType !== "lot" && blockedTrayStates.includes(trayState)) {
    return `BLOCKED: terminal product state (${row?.tray_state || "unknown"})`;
  }
  if (inventoryType !== "lot" && location === "shipped") {
    return "REVIEW: product currently recorded as Shipped";
  }
  if (String(row?.storage_location_id || "") === targetId) {
    return "Already correct";
  }
  if (location === "missingorlost") {
    return `Restore from Missing or Lost → ${targetName}`;
  }
  return `Move from ${row?.storage_location || "Unassigned"} → ${targetName}`;
}

