actionConfiguration.body:
function () {
  if (!InventoryReconcile.isSessionActive()) return "No active reconciliation.";
  const foundRows = appsmith.store.recon_found_rows || [];
  const missingRows = InventoryReconcile.missingRows();
  const plannedChanges = InventoryReconcile.changeRows();
  const plannedMissingRows = plannedChanges.filter(row => row.action === "Move to Missing or Lost");
  const terminalSkips = plannedChanges.filter(row => String(row.action || "").startsWith("SKIP:"));
  const foundProducts = foundRows.filter(row => InventoryReconcile.normalizeToken(row.inventory_type) === "product").length;
  const foundLots = foundRows.filter(row => InventoryReconcile.normalizeToken(row.inventory_type) === "lot").length;
  const missingProducts = plannedMissingRows.filter(row => InventoryReconcile.normalizeToken(row.inventory_type) === "product").length;
  const missingLots = plannedMissingRows.filter(row => InventoryReconcile.normalizeToken(row.inventory_type) === "lot").length;
  const moveRows = InventoryReconcile.foundRows().filter(row => row.action !== "Already correct");
  const shipped = InventoryReconcile.shippedFoundRows().length;
  const alreadyCorrect = InventoryReconcile.foundRows().filter(row => row.action === "Already correct").length;
  return [`Location: ${appsmith.store.recon_location_name || "selected location"}`, `Physically found: ${foundRows.length} (${foundProducts} products / ${foundLots} lots)`, `Already correct: ${alreadyCorrect}`, `Move/restore into location: ${moveRows.length}`, `Move to Missing or Lost: ${plannedMissingRows.length} (${missingProducts} products / ${missingLots} lots)`, `Terminal-state snapshot records that will be skipped: ${terminalSkips.length}`, `Shipped product corrections requiring audit notes: ${shipped}`, "", "Finalization is one PostgreSQL statement. Products or Lots that legitimately changed location after the starting snapshot are skipped rather than overwritten."].join("\n");
}

