actionConfiguration.body:
function () {
  if (!InventoryReconcile.isSessionActive()) return [];
  const targetName = appsmith.store.recon_location_name || "selected location";
  const foundChanges = InventoryReconcile.foundRows().filter(row => row.action !== "Already correct").map(row => ({
    inventory_type: row.inventory_type || "Record",
    inventory_id: row.inventory_id || row.product_id || row.lot_id || row.nocopk,
    action: row.action,
    from_location: row.storage_location || "Unassigned",
    to_location: targetName
  }));
  const missingChanges = InventoryReconcile.missingRows().map(row => {
    const inventoryType = InventoryReconcile.normalizeToken(row?.inventory_type);
    const trayState = InventoryReconcile.normalizeToken(row?.tray_state);
    const lotStatus = InventoryReconcile.normalizeToken(row?.status);
    const terminalProductStates = ["emptytray", "compost", "composted", "spoiled", "retired", "expired", "consumed", "shipped"];
    const terminalLotStatuses = ["consumed", "retired", "expired", "compost", "composted"];
    const isTerminal = inventoryType === "lot" ? terminalLotStatuses.includes(lotStatus) : terminalProductStates.includes(trayState);
    return {
      inventory_type: row.inventory_type || "Record",
      inventory_id: row.inventory_id || row.product_id || row.lot_id || row.nocopk,
      action: isTerminal ? `SKIP: terminal ${inventoryType === "lot" ? "Lot" : "Product"} state` : "Move to Missing or Lost",
      from_location: targetName,
      to_location: isTerminal ? targetName : "Missing or Lost"
    };
  });
  return [...foundChanges, ...missingChanges];
}

