  if (firstRow && firstRow.nocopk != null) {
    setTimeout(() => {
      LotsHarvest.openHarvestModal(firstRow).catch(e => {
        showAlert(e?.message || String(e), "error");
      });
    }, 300);
    return;
  }
  txtHarvestContent.setText("(No lots selected)");
  await resetWidget("inpHarvestFlushNo", false);
  await inpHarvestWeightG.setValue("");
  await inpHarvestFreshTrayCount.setValue("0");
  await inpHarvestFrozenTrayCount.setValue("1");
  await inpHarvestNotes.setValue("");
  await LotsHarvest.onHarvestCountsChanged();
}

