children.text:
{{(() => {
  const rows = Array.isArray(tblPrintQueue.selectedRows) ? tblPrintQueue.selectedRows : [];
  if (!rows.length) return "Select one or more print jobs.";
  const counts = rows.reduce((acc, row) => {
    const status = String(row?.print_status || "Unknown").trim() || "Unknown";
    acc[status] = (acc[status] || 0) + 1;
    return acc;
  }, {});
  const statusSummary = Object.entries(counts)
    .map(([status, count]) => `${status}: ${count}`)
    .join(" • ");
  const warning = rows.some(row => String(row?.print_status || "").trim().toLowerCase() === "printing")
    ? " • Active Printing job selected; changes are blocked."
    : "";
  return `${rows.length} job(s) selected • ${statusSummary}${warning}`;
})()}}

